const a={1:[["1","Yeşu'nun ölümünden sonra İsraelliler Yahve'ye sorup dediler: “Kenanlılar'a karşı savaşmak için bizim için ilk kim çıkacak?”"],["2","Yahve, “Yahuda çıkacak. İşte, ülkeyi onun eline teslim ettim” dedi."],["3","Yahuda, kardeşi Şimon'a, “Bana düşen paya benimle birlikte gel, Kenanlılar'a karşı savaşalım; ben de sana düşen paya seninle birlikte gideceğim” dedi. Böylece Şimon onunla birlikte gitti."],["4","Yahuda çıktı ve Yahve Kenanlılar'ı ve Perizziler'i onların eline teslim etti. Bezek'te on bin kişiyi vurdular."],["5","Bezek'te Adoni-Bezek'i buldular ve ona karşı savaştılar. Kenanlılar'ı ve Perizziler'i vurdular."],["6","Ama Adoni-Bezek kaçtı. Onu kovaladılar, yakaladılar ve ellerinin ve ayaklarının başparmaklarını kestiler."],["7","Adoni-Bezek, “Yetmiş kral, ellerinin ve ayaklarının başparmakları kesilmiş olarak soframın altındaki kırıntıları yediler. Ben nasıl yaptıysam, Tanrı da bana öyle yaptı” dedi. Onu Yeruşalem'e getirdiler ve orada öldü."],["8","Yahuda'nın çocukları Yeruşalem'e karşı savaştılar, onu aldılar, kılıçtan geçirdiler ve kenti ateşe verdiler."],["9","Bundan sonra Yahuda'nın çocukları dağlık bölgede, güneyde ve ovada yaşayan Kenanlılar'a karşı savaşmak için aşağı indiler."],["10","Yahuda, Hevron'da yaşayan Kenanlılar'a karşı gitti. (Hevron'un bundan önceki adı Kiryat Arba'ydı.) Şeşay'ı, Ahiman'ı ve Talmay'ı vurdular."],["11","Oradan Devir sakinlerine karşı yürüdüler. (Devir'in eski adı Kiryat Sefer'di.)"],["12","Kalev, “Kiryat Sefer'i vurup onu alan adama kızım Aksa'yı eş olarak vereceğim” dedi."],["13","Kalev'in küçük kardeşi Kenaz'ın oğlu Otniel orayı aldı, bu yüzden kızı Aksa'yı ona eş olarak verdi."],["14","Kadın gelince, adam kadına babasından bir tarla istetti. Eşeğinden indi ve Kalev ona, “Ne istersin?” diye sordu."],["15","Kalev, “Bana bir kutsama ver, çünkü beni Güney diyarına yerleştirdin, bana su kaynaklarını da ver” dedi. Sonra Kalev ona üst ve alt kaynakları verdi."],["16","Moşe'nin kayınbiraderi Kenit'in çocukları, Yahuda'nın çocuklarıyla birlikte Palmiye Ağaçları Kenti'nden çıkıp Arad'ın güneyindeki Yahuda Çölü'ne gittiler ve gidip halkla birlikte yaşadılar."],["17","Yahuda, kardeşi Şimon'la birlikte gitti ve Sefat'ta oturan Kenanlılar'ı vurup tamamen yok ettiler. Kente Horma deniliyordu."],["18","Yahuda üstelik Gaza'yı sınırıyla, Aşkelon'u sınırıyla, Ekron'u sınırıyla aldı."],["19","Yahve Yahuda'yla birlikteydi ve dağlık bölgenin sakinlerini kovdu; ancak vadi sakinlerini kovamadı, çünkü demirden arabaları vardı."],["20","Moşe'nin söylediği gibi Hevron'u Kalev'e verdiler, o da Anak'ın üç oğlunu oradan kovdu."],["21","Benyamin'in çocukları Yeruşalem'de oturan Yevuslular'ı kovmadılar; ama Yevuslular bugüne dek Yeruşalem'de Benyamin'in çocukları ile birlikte oturuyorlar."],["22","Yosef'in evi de Beytel'e çıktı ve Yahve onlarla birlikteydi."],["23","Yosef'in evi Beytel'i araştırmak için adam gönderdi. (Kentin bundan önceki adı Luz'du.)"],["24","Gözcüler kentten çıkan bir adam gördüler ve ona, “Lütfen bize kentin girişini göster, sana iyilikle davranacağız” dediler."],["25","O da onlara kentin girişini gösterdi, kenti kılıçtan geçirdiler; ama adamı ve bütün ailesini salıverdiler."],["26","Adam Hititler ülkesine gitti, bir kent kurdu ve adını Luz koydu; bugüne dek adı budur."],["27","Manaşşe, Beyt Şean ve köylerinin sakinlerini, Taanak ve köylerinin sakinlerini, Dor ve köylerinin sakinlerini, İvleam ve köylerinin sakinlerini, Megiddo ve köylerinin sakinlerini kovmadı; ama Kenanlılar o ülkede oturmaya niyetliydi."],["28","İsrael güçlenince Kenanlılar'ı angaryaya koydular ve onları tümüyle kovmadılar."],["29","Efraim, Gezer'de yaşayan Kenanlılar'ı kovmadı, ama Kenanlılar Gezer'de onların arasında yaşadılar."],["30","Zevulun, Kitron sakinlerini ve Nahalol sakinlerini kovmadı; ama Kenanlılar onların arasında yaşadılar ve angaryaya tabi oldular."],["31","Aşer, Akko sakinlerini, Sayda sakinlerini, Ahlav sakinlerini, Akziv sakinlerini, Helba sakinlerini, Afik sakinlerini ve Rehov sakinlerini kovmadı;"],["32","ancak Aşerliler, memleketin sakinleri olan Kenanlılar arasında yaşıyorlardı; çünkü onları kovmadılar."],["33","Naftali, Beyt Şemeş sakinlerini ve Beyt Anat sakinlerini kovmadı; ama memleketin sakinleri olan Kenanlılar arasında yaşıyordu. Ancak Beyt Şemeş ve Beyt Anat sakinleri angaryaya tabi tutuldular."],["34","Amorlular, Dan'ın çocuklarını dağlık bölgeye zorladılar; çünkü onların vadiye inmelerine izin vermiyorlardı;"],["35","ama Amorlular Heres Dağı'nda, Ayalon'da ve Şaalvim'de oturmaya niyetliydiler. Ancak Yosef'in evinin eli üstün geldi, böylece angaryaya tabi tutuldular."],["36","Amorlular'ın sınırı, Akrabbim'in yokuşundan, kayadan yukarıya doğruydu."]],2:[["1","Yahve'nin meleği Gilgal'dan Bokim'e çıktı. Ve şöyle dedi, “Sizi Mısır'dan çıkardım ve atalarınıza vermeye ant içtiğim ülkeye getirdim. 'Sizinle olan antlaşmamı asla bozmayacağım dedim."],["2","Bu ülkenin sakinleriyle antlaşma yapmayacaksınız. Sunaklarını yıkacaksınız.' Ama sözümü dinlemediniz. Bunu neden yaptınız?"],["3","Bu yüzden şunu da dedim, 'Onları önünüzden kovmayacağım; ama böğrünüzde olacaklar, ilâhları da size tuzak olacak.'”"],["4","Yahve'nin meleği bu sözleri bütün İsrael'in çocuklarına söylediğinde, halk seslerini yükseltip ağladı."],["5","O yerin adına Bokim dediler ve orada Yahve'ye kurban kestiler."],["6","Yeşu halkı gönderdiğinde, İsrael'in çocukları ülkeyi mülk edinmek için her biri kendi mirasına gitti."],["7","Halk, Yeşu'nun bütün günlerinde ve Yahve'nin İsrael için yaptığı bütün büyük işi görmüş olup Yeşu'dan sonra yaşayan ihtiyarların günlerinde Yahve'ye hizmet etti."],["8","Yahve'nin hizmetkârı Nun oğlu Yeşu yüz on yaşında öldü."],["9","Onu, Efraim dağlık bölgesindeki Timnat Heres'te, Gaaş Dağı'nın kuzeyindeki mirasının sınırına gömdüler."],["10","O kuşağın hepsi atalarına kavuştuktan sonra, onlardan sonra Yahve'yi ve İsrael için yaptığı işi bilmeyen başka bir kuşak yetişti."],["11","İsraelliler Yahve'nin gözünde kötü olanı yaptılar ve Baal'lara hizmet ettiler."],["12","Onları Mısır diyarından çıkaran atalarının Tanrısı Yahve'yi bıraktılar, çevrelerinde olan ulusların ilâhlarından olan başka ilâhların ardına düştüler ve onlara eğildiler; Yahve'yi öfkelendirdiler."],["13","Yahve'yi bırakıp Baal'a ve Aştarot'a hizmet ettiler."],["14","Yahve'nin öfkesi İsrael'e karşı alevlendi ve onları yağmalayan akıncıların eline teslim etti. Onları çevredeki düşmanlarının eline sattı, böylece artık düşmanlarının önünde duramaz oldular."],["15","Her nereye çıktılarsa, Yahve'nin eli kötülük için onlara karşıydı, Yahve'nin söylemiş olduğu gibi ve Yahve'nin onlara ant içmiş olduğu gibi; çok da sıkıntı çektiler."],["16","Yahve, onları yağmalayanların elinden kurtaran hâkimler çıkardı."],["17","Yine de hâkimlerini dinlemediler; çünkü başka ilâhlarla fahişelik ettiler ve onlara eğildiler. Atalarının Yahve'nin buyruklarını tutarak yürüdüğü yoldan onlar hemen saptılar. Onlar öyle yapmadılar."],["18","Yahve onlar için hâkimler çıkardığında, Yahve hâkimlerle birlikteydi ve hâkimin bütün günlerinde onları düşmanlarının elinden kurtardı; çünkü onları ezen ve sıkıntıya sokanların yüzünden inlemeleri Yahve'yi üzüyordu."],["19","Ama hâkim ölünce geri döndüler, başka ilâhlara hizmet edip onlara eğilmek için, onların peşinden gitmekte atalarından daha da çok yozlaştılar; Yaptıklarını bırakmadılar ve inatçı yollarından vazgeçmediler."],["20","Yahve'nin öfkesi İsrael'e karşı alevlendi ve şöyle dedi: “Çünkü bu ulus atalarına buyurduğum antlaşmamı bozdu ve sözümü dinlemedi,"],["21","ben de Yeşu öldüğünde bıraktığı uluslardan hiçbirini artık önlerinden kovmayacağım,"],["22","ta ki, atalarının tuttuğu gibi Yahve'nin yolunda yürüyüp yürümeyeceklerini, görmek için onlarla İsrael'i sınayacağım.”"],["23","Böylece Yahve o ulusları çabucak kovmadan bıraktı. Onları Yeşu'nun eline teslim etmedi."]],3:[["1","İşte bunlar, İsrael'i bütün Kenan savaşlarını bilmeyenlerin hepsini onlar aracılığıyla denesin,"],["2","yalnızca İsrael'in çocukları kuşaklarının, en azından savaşları daha önceden hiç bilmeyenlerin savaş öğrenme bilgileri olsun diye Yahve'nin bıraktığı uluslardır:"],["3","Filistliler'in beş beyi, bütün Kenanlılar, Saydalılar ve Lübnan Dağı'nda, Baal Hermon Dağı'ndan Hamat girişine kadar yaşayan Hivliler."],["4","Onlar, İsrael'i denemek, Yahve'nin Moşe aracılığıyla atalarına buyurduğu buyrukları dinleyip dinlemeyeceklerini bilmek için yanlarında bırakıldılar."],["5","İsrael'in çocukları Kenanlılar, Hititliler, Amorlular, Perizililer, Hivliler ve Yevuslular arasında yaşadılar."],["6","Kızlarını eş olarak aldılar, kendi kızlarını da oğullarına verdiler ve onların ilâhlarına hizmet ettiler."],["7","İsraelliler, Yahve'nin gözünde kötü olanı yaptılar ve Tanrıları Yahve'yi unuttular ve Baal'lara ve Aşera'ya hizmet ettiler."],["8","Bu yüzden Yahve'nin öfkesi İsrael'e karşı alevlendi ve onları Mezopotamya Kralı Kuşan Rişatayim'in eline sattı; ve İsraelliler sekiz yıl Kuşan Rişatayim'e hizmet ettiler."],["9","İsraelliler Yahve'ye yakardıklarında, Yahve İsraelliler için bir kurtarıcı çıkardı; bu, Kalev'in küçük kardeşi Kenaz'ın oğlu Otniel'di."],["10","Yahve'nin Ruhu onun üzerine geldi ve İsrael'e hükmetti; ve savaşa çıktı ve Yahve Mezopotamya Kralı Kuşan Rişatayim'i onun eline teslim etti. Eli Kuşan Rişatayim'e karşı galip geldi."],["11","Ülke kırk yıl dinlendi, sonra Kenaz'ın oğlu Otniel öldü."],["12","İsraelliler yine Yahve'nin gözünde kötü olanı yaptılar. Yahve, Moav Kralı Eglon'u İsraiel'e karşı güçlendirdi. Çünkü Yahve'nin gözünde kötü olanı yapmışlardı."],["13","Ammon'un ve Amalek'in çocuklarını yanına topladı. Gidip İsrael'i vurdu. Palmiye Ağaçları Kenti'ni ele geçirdiler."],["14","İsraelliler Moav Kralı Eglon'a on sekiz yıl hizmet ettiler."],["15","İsraelliler Yahve'ye yakardıklarında, Yahve onlar için bir kurtarıcı çıkardı: Benyaminli Gera'nın oğlu, solak bir adam olan Ehud. İsraelliler onun aracılığıyla Moav Kralı Eglon'a haraç gönderdiler."],["16","Ehud kendine iki ağızlı, bir arşın uzunluğunda bir pala yaptı. Bunu sağ uyluğunda, giysisinin altında kuşandı."],["17","Haracı Moav Kralı Eglon'a sundu. Eglon çok şişman bir adamdı."],["18","Ehud haraç sunmayı bitirince, haracı taşıyan adamları gönderdi."],["19","Ama kendisi Gilgal'ın yanındaki taş putlardan geri döndü ve, “Ey kral, sana gizli bir haberim var” dedi. Kral, “Sus!” dedi. Yanında duranların hepsi ayrıldı."],["20","Ehud yanına geldi; ve o, serin üst odada tek başına oturuyordu. Ehud, “Tanrı'dan sana bir haberim var” dedi. Oturduğu yerden kalktı."],["21","Ehud sol elini uzattı ve sağ uyluğundan palayı alıp onun vücuduna sapladı."],["22","Palanın sapı da ucunun ardından girdi; ve yağ ucunun üzerine kapandı, çünkü palayı vücudundan çekmedi; pala da arkadan çıktı."],["23","Bunun üzerine Ehud verandaya çıktı, üst kattaki odanın kapılarını onun üzerine kapatıp kilitledi."],["24","O gittikten sonra hizmetkârları gelip üst odanın kapılarının kilitli olduğunu gördüler. “Kesin o, üst kattaki odada ayaklarını örtüyor” dediler."],["25","Sıkılıncaya kadar beklediler; ve işte, o, üst odanın kapısını açmadı. Bunun üzerine anahtarı alıp açtılar ve bir baktılar ki, efendileri ölü bir şekilde yere düşmüştü."],["26","Onlar beklerken Ehud kaçtı, taş putların ötesine geçerek Seira'ya kaçtı."],["27","Gelince Efraim'in dağlık bölgesinde boru çaldı. ve İsrael'in çocukları dağlık bölgeden onunla birlikte indiler; o da onlara öncülük etti."],["28","Onlara şöyle dedi: “Beni takip edin; çünkü Yahve düşmanlarınız Moavlılar'ı elinize teslim etti.” Onu takip ettiler ve Yarden'in geçitlerini Moavlılar'a karşı ele geçirdiler ve kimsenin geçmesine izin vermediler."],["29","O sırada Moavlılar'ın her biri güçlü ve yiğit olmak üzere yaklaşık on bin kişiyi vurdular. Kimse kaçamadı."],["30","Böylece Moav o gün İsrael'in eli altında boyun eğdirildi. Daha sonra ülke seksen yıl rahat etti."],["31","Ondan sonra Anat'ın oğlu Şamgar vardı ve Filistliler'den altı yüz kişiyi öküz üvendiresiyle vurdu. O da İsrael'i kurtardı."]],4:[["1","Ehud öldüğünde İsrael'in çocukları yine Yahve'nin gözünde kötü olanı yaptılar."],["2","Yahve onları Hasor'da hüküm süren Kenan Kralı Yavin'in eline sattı; ordusunun komutanı, öteki ulusların Haroşet'inde yaşayan Sisera idi."],["3","İsrael'in çocukları Yahve'ye yakardılar; çünkü onun dokuz yüz demir arabası vardı; yirmi yıl boyunca da İsrael'in çocuklarına çok baskı yaptı."],["4","O sırada Lappidot'un karısı Peygamber Devora İsrael'e hükmediyordu."],["5","O, Efraim'in dağlık bölgesindeki Rama ile Beytel arasındaki Devora'nın palmiye ağacının altında yaşıyordu; İsrael'in çocukları da hüküm için onun yanına çıkarlardı."],["6","Gönderip Avinoam oğlu Barak'ı Kedeş Naftali'den çağırdı ve ona şöyle dedi: “İsrael'in Tanrısı Yahve, 'Git, yanına Naftali'nin çocuklarından ve Zevulun'un çocuklarından on bin kişi alıp Tabor Dağı'na götür' diye buyurmadı mı?"],["7","'Yavin'in ordusunun komutanı Sisera'yı onun savaş arabaları ve kalabalığıyla birlikte Kişon Irmağı'na, sana doğru çekeceğim; onu senin eline teslim edeceğim.'”"],["8","Barak ona şöyle dedi: “Benimle geleceksen giderim; ama sen benimle gelmeyeceksen ben de gitmem.”"],["9","O, “Ben kesinlikle seninle geleceğim” dedi. “Ancak çıkacağın yolculuk senin onuruna olmayacak; çünkü Yahve Sisera'yı bir kadının eline satacak.” Devora kalktı ve Barak'la birlikte Kedeş'e gitti."],["10","Barak Zevulun ile Naftali'yi birlikte Kedeş'e çağırdı. On bin adam onu takip etti; Devora da onunla birlikte yukarı çıktı."],["11","Kenli Hever, Moşe'nin kayınbiraderi Hovav'ın çocuklarından, Kenliler'den kendini ayırmıştı ve çadırını Kedeş yakınındaki Zaanannim'deki meşe ağacına kadar kurmuştu."],["12","Sisera'ya Avinoam oğlu Barak'ın Tavor Dağı'na çıktığını bildirdiler."],["13","Sisera, öteki ulusların Haroşet'inden Kişon Irmağı'na kadar bütün savaş arabalarını, dokuz yüz demir savaş arabasını da ve kendisiyle birlikte olan bütün halkı bir araya topladı."],["14","Devora Barak'a, “Git; çünkü bu, Yahve'nin Sisera'yı elinize teslim ettiği gündür. Yahve senin önünden çıkmadı mı?” dedi. Böylece Barak ve ardında on bin kişi Tabor Dağı'ndan indi."],["15","Yahve Sisera'yı, savaş arabalarını ve ordusunu Barak'ın önünde kılıçtan geçirip şaşkına çevirdi. Sisera arabasını bırakıp yaya kaçtı."],["16","Ama Barak savaş arabalarını ve orduyu öteki ulusların Haroşet'ine kadar kovaladı; Sisera'nın bütün ordusu da kılıçtan geçirildi. Bir kişi bile kalmadı."],["17","Ne var ki Sisera, Kenli Hever'in karısı Yael'in çadırına yaya kaçtı; çünkü Hasor Kralı Yavin ile Kenli Hever'in evi arasında barış vardı."],["18","Yael, Sisera'yı karşılamaya çıktı ve ona şöyle dedi: “Efendim, dön, bana dön; korkma.” Çadırın içine onun yanına girdi ve onu bir kilimle örttü."],["19","O, “Lütfen bana içmem için biraz su ver; çünkü susadım” dedi. Bir süt kabı açtı, ona içirdi ve üzerini örttü."],["20","O ona şöyle dedi: “Çadırın kapısında dur; eğer biri gelip sana sorarsa ve 'Burada kimse var mı?' derse, 'Hayır' diyeceksin.”"],["21","Sonra Hever'in karısı Yael, bir çadır kazığı aldı ve tokmağı elinde tuttu, yavaşça ona doğru gitti ve kazığı şakaklarına vurdu, kazık da yere kadar delip geçti; çünkü o derin uykudaydı; bu yüzden bayıldı ve öldü."],["22","İşte Barak Sisera'yı kovalarken Yael onu karşılamaya çıktı ve ona, “Gel, sana aradığın adamı göstereyim” dedi. Yanına geldi; ve işte, Sisera ölü yatıyordu ve çadır kazığı şakaklarındaydı."],["23","Böylece Tanrı o gün Kenan Kralı Yavin'i İsrael'in çocuklarının önünde boyun eğdirdi."],["24","Kenan Kralı Yavin'i yok edene dek, İsrael çocuklarının eli, Kenan Kralı Yavin'e karşı giderek daha da güçlendi."]],5:[["1","O gün Devora ile Avinoam oğlu Barak ezgi söyleyip dediler:"],["2","“İsrael'de önderler öncülük ettikleri için, halk gönüllü olarak kendilerini sundukları için, yücelsin Yahve!”"],["3","“Duyun, ey krallar! Kulak verin ey beyler! Ben, Yahve'ye ben ezgi söyleyeceğim. İsrael'in Tanrısı Yahve'yi ezgiyle öveceğim.”"],["4","“Ey Yahve, Seir'den çıktığın zaman, Edom kırından yürüdüğün zaman Yeryüzü sarsıldı, gökyüzü de damlattı. Evet, bulutlar su damlattı."],["5","Dağlar Yahve'nin önünde, Sina Dağı bile İsrael'in Tanrısı Yahve'nin önünde sarsıldı.”"],["6","“Anat oğlu Şamgar'ın günlerinde, Yael'in günlerinde de ana yollar boştu. Yolcular sapa yollardan geçtiler."],["7","İsrael'de hâkimler sona erdi. Ben Devora ayağa kalkana dek kesildiler; ta ki, İsrael'de bir ana olarak ben ortaya çıkana dek."],["8","Onlar yeni ilâhlar seçtiler. O zaman savaş kapılardaydı. İsrael'de kırk bin arasında kalkan ya da mızrak görüldü mü?"],["9","Yüreğim kendilerini halkın arasında gönüllü olarak sunan İsrael önderlerinden yanadır. Yahve'yi yüceltin!”"],["10","“Ey beyaz eşeklere binenler, ey gösterişli halılar üzerinde oturanlar ve ey yolda yürüyenler, söyleyin."],["11","Okçuların gürültüsünden uzak, su çekilen yerlerde, Yahve'nin doğru işlerini, O'nun İsrael'deki yönetiminin doğru işlerini anlatacaklar. “O zaman Yahve'nin halkı kapılara indi.”"],["12","'Uyan, uyan, Devora! Uyan, uyan, bir ezgi söyle! Kalk ey Barak, ey Abinoam oğlu, tutsaklarını götür.'”"],["13","“Sonra soyluların ve halkın geri kalanları aşağı indi. Yahve güçlülere karşı benim için indi."],["14","Kökü Amalek'te olanlar, senin halklarının arasında Senden sonra Benyamin'den, Efraim'den çıktılar. Yöneticiler Makir'den indiler. Mareşalin asasını idare edenler Zevulun'dan geldi."],["15","İssakar beyleri Devora'nın yanındaydı. İssakar nasılsa Barak da öyleydi. Ayaklarının dibindeki vadiye koştular. Ruven'in su yollarının yanında yüreğin önemli kararları vardı."],["16","Neden koyun ağıllarının arasında oturdun? Sürülerin ıslık sesini duymak için mi? Ruven'in su yollarında yüreğin önemli arayışları vardı."],["17","Gilad Yarden'in ötesinde yaşıyordu. Dan neden gemilerde kaldı? Asher denizin limanında kıpırdamadan oturuyor ve derelerinin kıyısında yaşıyordu."],["18","Zevulun canlarını ölüme kadar tehlikeye atan bir halktı; Naftali de meydanın yüksek yerlerindeydi.”"],["19","“Krallar gelip savaştılar; sonra Kenan kralları Megiddo suları kıyısındaki Taanak'ta savaştılar. Hiç gümüş yağmalamadılar."],["20","Gökyüzünden yıldızlar savaştılar. Sisera'ya karşı rotalarından savaştılar."],["21","Kişon Irmağı, o eski ırmak, Kişon Irmağı onları süpürüp attı. Ey ruhum, üzerlerine güçle yürü."],["22","Sonra atların şahlanması yüzünden, güçlülerinin şahlanması yüzünden, at toynakları yere damga vurdular."],["23","Yahve'nin meleği, 'Meroz'a lanetleyin' dedi. ‘Orada yaşayanları ağır bir şekilde lanetleyin, Çünkü onlar Yahve'nin yardımına, Güçlülere karşı Yahve'nin yardımına gelmediler.’”"],["24","“Kenli Hever'in karısı, Yael, kadınlar arasında fazlasıyla kutsanacak; çadır kadınları arasında fazlasıyla kutsansın."],["25","Su istedi. Kadın ona süt verdi. Ona efendilere layık bir tabakta tereyağı getirdi."],["26","Elini çadır kazığına, sağ elini de işçi tokmağına koydu. Tokmakla Sisera'yı vurdu. Kafasına çaktı. Evet, şakaklarından delip geçirdi."],["27","Onun ayaklarına kapandı, düşüp yattı. Ayaklarının dibinde eğildi, düştü. Eğildiği o yere, ölü düştü.”"],["28","“Kadın pencereden dışarı baktı ve bağırdı: Sisera'nın annesi kafesten baktı. 'Arabasının gelmesi neden bu kadar uzun sürüyor? Arabalarının tekerlekleri neden bekliyor?'"],["29","Bilge hanımları ona yanıt verdi, evet, kendi kendine yanıt verdi,"],["30","'Bir kız, her erkeğe iki kız; Sisera'ya boyalı giysi yağması, işlenmiş boyalı giysi yağması, yağma olarak iki yanı işlenmiş boyalı giysi, ganimeti bulup da paylaşmadılar mı?'"],["31","“Bütün düşmanların yok olsun, ey Yahve, ama O'nu sevenler, gücünde doğan güneş gibi olsunlar.” Ondan sonra ülke kırk yıl rahat etti."]],6:[["1","İsrael'in çocukları Yahve'nin gözünde kötü olanı yaptılar. Bunun üzerine Yahve onları yedi yıl Midyanlılar'ın eline teslim etti."],["2","Midyan'ın eli İsrael'e galip geldi; Midyan yüzünden de İsrael'in çocukları kendilerine dağlarda bulunan sığınaklar, mağaralar ve kaleler yaptılar."],["3","Böylece İsrael ektikten sonra Midyanlılar, Amalekliler ve doğunun çocukları onlara karşı çıkarlardı."],["4","Onlara karşı ordugâh kurup Gaza'ya gelinceye dek yerin ürününü yok ederlerdi. Koyun olsun, öküz olsun, eşek olsun, İsrael'de yiyecek bırakmazlardı."],["5","Çünkü hayvanları ve çadırlarıyla birlikte gelirlerdi. Çekirge gibi kalabalık gelirlerdi. Hem kendilerinin hem de develerinin sayısı çoktu; ve ülkeyi yok etmek için gelirlerdi."],["6","Midyan yüzünden İsrael çok alçaldı; İsrael'in çocukları da Yahve'ye feryat ettiler."],["7","İsrael'in çocukları Midyan yüzünden Yahve'ye yakarınca,"],["8","Yahve İsrael'in çocuklarına bir peygamber gönderdi; ve onlara şöyle dedi: “İsrael'in Tanrısı Yahve diyor ki, 'Sizi Mısır'dan ben çıkardım ve esaret evinden çıkardım."],["9","Sizi Mısırlılar'ın elinden ve size baskı yapanların hepsinin elinden ben kurtardım, onları sizin önünüzden kovdum ve onların ülkelerini size verdim."],["10","Size şöyle dedim: “Ben Tanrınız Yahve'yim. Ülkesinde oturduğunuz Amorlular'ın ilâhlarından korkmayacaksınız.” Ama siz sözümü dinlemediniz.'”"],["11","Yahve'nin meleği gelip Aviezerli Yoaş'ın Ofra Kenti'ndeki meşe ağacının altına oturdu. Oğlu Gidyon, buğdayı Midyanlılar'dan saklamak için üzüm sıkma çukurunda dövüyordu."],["12","Yahve'nin meleği ona görünüp şöyle dedi: “Ey cesur yiğit, Yahve seninledir!”"],["13","Gidyon ona şöyle dedi: “Efendim, eğer Yahve bizimleyse, bütün bunlar neden başımıza geldi? Atalarımızın, 'Yahve bizi Mısır'dan çıkarmadı mı?' diyerek bize anlattığı bütün O'nun harika işleri nerede? Ama şimdi Yahve bizi attı ve Midyan'ın eline teslim etti.”"],["14","Yahve ona baktı ve şöyle dedi: “Bu gücünle git ve İsrael'i Midyan'ın elinden kurtar. Seni ben göndermedim mi?”"],["15","O da O'na, “Ey Efendim, İsrael'i nasıl kurtaracağım?” dedi. “İşte, benim ailem Manaşşe'nin en yoksulu, ben de babamın evinde en küçüğüyüm.”"],["16","Yahve ona, “Kesinlikle ben seninle olacağım ve sen Midyanlılar'ı bir adammış gibi vuracaksın” dedi."],["17","O'na şöyle dedi: “Eğer şimdi senin gözünde lütuf bulduysam, benimle konuşanın sen olduğunu gösteren bana bir belirti göster."],["18","Lütfen ben yanına gelip hediyemi çıkarıncaya dek, önüne koyuncaya dek, buradan ayrılma.” “Sen dönene dek bekleyeceğim” dedi."],["19","Gidyon içeri girip bir oğlak ve bir efalık mayasız pideler hazırladı. Eti bir sepete koydu, et suyunu da bir tencereye koyup meşe ağacının altına getirip O'na sundu."],["20","Tanrı'nın meleği ona, “Eti ve mayasız pideleri al, bu kayanın üzerine koy ve et suyunu dök” dedi. O da öyle yaptı."],["21","Bunun üzerine Yahve'nin meleği elindeki değneğin ucunu uzattı, ete ve mayasız pidelere dokundu; ve kayadan ateş çıkıp etleri ve mayasız pideleri yiyip bitirdi. Sonra Yahve'nin meleği gözünün önünden ayrıldı."],["22","Gidyon O'nun Yahve'nin meleği olduğunu gördü; Gidyon şöyle dedi: “Eyvah, Ey Efendi Yahve! Çünkü Yahve'nin meleğini yüz yüze gördüm!”"],["23","Yahve ona şöyle dedi: “Esenlik olsun sana! Korkma. Ölmeyeceksin.”"],["24","Bunun üzerine Gidyon orada Yahve'ye bir sunak yaptı ve ona, “Yahve Esenliktir” adını verdi. Bu sunak bugüne dek hâlâ Aviezerliler'in Ofra Kenti'ndedir."],["25","Aynı gece Yahve ona şöyle dedi: “Babanın yedi yaşındaki ikinci boğasını al, babanın Baal sunağını yık ve yanındaki Aşera'yı kes."],["26","Sonra bu kalenin tepesinde Tanrın Yahve'ye düzenine göre bir sunak yap, ikinci boğayı al ve keseceğin Aşera odunuyla yakmalık sunu sun.”"],["27","Bunun üzerine Gidyon hizmetkârlarından on kişiyi aldı ve Yahve'nin kendisine söylediği gibi yaptı. Babasının ev halkından ve kentin insanlarından korktuğu için bunu gündüz yapamadı ama gece yaptı."],["28","Kentin insanları sabah erkenden kalktılar, işte, Baal'ın sunağı yıkılmıştı, yanındaki Aşera kesilmişti ve ikinci boğa yapılan sunağın üzerinde sunulmuştu."],["29","Birbirlerine, “Bu şeyi kim yaptı?” dediler. Sorup soruşturduklarında, “Bunu Yoaş oğlu Gidyon yaptı” dediler."],["30","Kentin insanları Yoaş'a, “Oğlunu dışarı çıkar da ölsün” dediler, “Çünkü o Baal'ın sunağını yıktı ve onun yanındaki Aşera'yı kesti.”"],["31","Yoaş kendisine karşı çıkanların hepsine şöyle dedi: “Baal için siz mi çekişeceksiniz? Yoksa onu siz mi kurtaracaksınız? Onun için çekişecek olan, sabaha öldürülsün! Eğer o bir ilâhsa, birisi onun sunağını yıktı diye kendisi çekişsin!”"],["32","Bu nedenle o gün ona Yerub-Baal adını verdi ve şöyle dedi: “Baal onunla çekişsin, çünkü o onun sunağını yıktı.”"],["33","Bunun üzerine bütün Midyanlılar, Amalekliler ve doğunun çocukları bir araya toplandılar; ve geçip Yizreel Vadisi'nde ordugâh kurdular."],["34","Ama Yahve'nin Ruhu Gidyon'un üzerine indi ve o boru çaldı. Aviezer de onu takip etmek üzere toplandı."],["35","Manaşşe'nin her yerine ulaklar gönderdi; onlar da onu takip etmek üzere bir araya toplandılar. Aşer'e, Zevulun'a ve Naftali'ye ulaklar gönderdi; ve onları karşılamaya çıktılar."],["36","Gidyon Tanrı'ya şöyle dedi: “Eğer söylediğin gibi İsrael'i benim ellerimle kurtaracaksan,"],["37","işte, harman yerine yün yapağı koyacağım. Yalnızca yapağının üzerinde çiy varsa ve toprağın tümü kuruysa, o zaman söylediğin gibi İsrael'i benim ellerimle kurtaracağını bileceğim.”"],["38","Öyle oldu; çünkü ertesi gün erkenden kalktı, yapağıyı sıktı ve yapağının içinden bir tas dolusu su çıkardı."],["39","Gidyon Tanrı'ya şöyle dedi: “Bana karşı öfken alevlenmesin, bu seferlik konuşacağım. Lütfen yalnızca bu seferlik yapağıyla bir deneme yapayım. Şimdi yapağının üstü kuru olsun, toprağın tümü üzerinde de çiy olsun.”"],["40","Tanrı o gece öyle yaptı; çünkü yalnızca yapağının üstü kuruydu ve toprağın tümünde çiy vardı."]],7:[["1","Bunun üzerine Yerubbaal, yani Gidyon ve onunla birlikte olanların tümü erkenden kalkıp Harod Pınarı yanında ordugâh kurdular. Midyan ordugâhı kuzey tarafında, vadideki Moreh Tepesi'nin yanındaydı."],["2","Yahve Gidyon'a şöyle dedi: “İsrael, 'Beni kendi elim kurtardı' diyerek övünmesin diye, seninle birlikte olanların sayısı Midyanlılar'ı onların eline veremeyeceğim kadar çok."],["3","Şimdi bunu halkın kulağına duyurup de, 'Korkan ve titreyen kimse geri dönsün ve Gilad Dağı'ndan ayrılsın.'” Böylece halktan yirmi iki bin kişi geri döndü ve on bin kişi kaldı."],["4","Yahve Gidyon'a şöyle dedi: “Hâlâ çok fazla insan var. Onları suya indir, ben de onları senin için orada sınayacağım. Öyle olacak ki sana, 'Bu seninle gidecek' dediğim kişi seninle birlikte gidecek; ve sana, 'Bu seninle gitmeyecek' dediğim kişi gitmeyecek.”"],["5","Bunun üzerine halkı suya indirdi; ve Yahve Gidyon'a şöyle dedi: “Köpek gibi suyu diliyle içen her kişiyi ayrı; içmek için dizleri üzerine çöken her kişiyi de ayrı koyacaksın.”"],["6","Ellerini ağızlarına götürüp dilleriyle içenlerin sayısı üç yüz kişiydi; ama halkın geri kalanlarının hepsi su içmek için dizleri üzerine çöktüler."],["7","Yahve Gidyon'a şöyle dedi: “Seni dille içen üç yüz adamla kurtaracağım ve Midyanlılar'ı eline teslim edeceğim. Diğer herkes kendi yerine gitsin.”"],["8","Halk ellerine yiyecek ve borularını aldı; ve geri kalan İsrael adamlarının hepsini kendi çadırlarına gönderdi, ama üç yüz kişiyi alıkoydu; Midyan'ın ordugâhı onun altında, vadideydi."],["9","Aynı gece Yahve ona şöyle dedi: “Kalk, ordugâha in; çünkü orayı sana teslim ettim."],["10","Ama aşağı inmeye korkuyorsan, uşağın Purah'la birlikte ordugâha gidin."],["11","Ne dediklerini duyacaksın; ve sonra ordugâha inmek için ellerin kuvvetlendirilecek.” Sonra uşağı Purah'la birlikte ordugâhtaki silahlı adamların en dış kısmına indiler."],["12","Midyanlılar, Amalekliler ve doğunun bütün çocukları, kalabalık çekirgeler gibi vadide yatıyorlardı; ve develeri, deniz kıyısındaki kumların çokluğu gibi sayısızdı."],["13","Gidyon geldiğinde, işte, arkadaşına rüyasını anlatan bir adam vardı. Şöyle dedi: “İşte, bir rüya gördüm; ve işte, arpa ekmeğinden bir somun Midyan ordugâhına yuvarlandı, çadıra geldi ve ona çarpıp düşürdü ve onu baş aşağı döndürdü, öyle ki çadır dümdüz oldu.”"],["14","Arkadaşı şöyle yanıt verdi: “Bu, İsraelli Yoaş oğlu Gidyon'un kılıcından başka bir şey değil. Tanrı Midyan'ı bütün orduyla birlikte onun eline teslim etti.”"],["15","Gidyon rüyanın anlatıldığını ve yorumlandığını duyunca tapındı. Sonra İsrael ordugâhına dönüp şöyle dedi: “Kalkın, çünkü Yahve Midyan ordusunu elinize teslim etti!”"],["16","Üç yüz adamı üç bölüğe ayırdı ve hepsinin eline boruları, içi meşalelerle birlikte boş testileri verdi."],["17","Onlara, “Beni izleyin, siz de aynısını yapın” dedi. “İşte, ordugâhın en dış kısmına geldiğimde, öyle olacak ki, benim yaptığımı siz de yapacaksınız."],["18","Boru çaldığım zaman, ben ve yanımdaki herkes, ordugâhın her yanında boruları çalın ve 'Yahve için, Gidyon için' diye bağırın.”"],["19","Böylece Gidyon ve onunla birlikte olan yüz adam orta nöbetin başlangıcında, nöbetçileri henüz yeni koyduklarında ordugâhın en dış kısmına geldiler. Daha sonra boru çaldılar ve ellerindeki testileri kırdılar."],["20","Üç bölük boru çaldılar, testileri kırdılar, meşaleleri sol ellerinde, boruları çalmak için sağ ellerinde tuttular; ve “Yahve'nin ve Gidyon'un kılıcı!” diye bağırdılar."],["21","Herkes ordugâhın çevresinde kendi yerlerinde durdu ve bütün ordu koştu; bağırdılar ve onları kaçırdılar."],["22","Üç yüz boru çaldılar ve Yahve her birinin kılıcını arkadaşına karşı ve bütün orduya karşı koydu; ve ordu Beyt Şitta'ya, Sereray'a doğru, Tabbat yanındaki Avel Mehola sınırına kadar kaçtı."],["23","İsrael adamları Naftali'den, Aşer'den ve bütün Manaşşe'den toplanıp Midyan'ı kovaladılar."],["24","Gidyon Efraim'in bütün dağlık bölgesine ulaklar göndererek şöyle dedi: “Midyan'a karşı inin ve önlerinde Beytbara'ya kadar suları, Yarden'i alın!” Böylece bütün Efrayim adamları bir araya toplanıp Beytbara'ya kadar suları, Yarden'i de aldılar."],["25","Midyan'ın iki beyi Orev ile Zeev'i tuttular. Orev'i Orev'in Kayası'nda öldürdüler ve Zeev'i de Midyan'ı kovalarken Zeev'in üzüm sıkma çukurunda öldürdüler. Daha sonra Orev ile Zeev'in başlarını Yarden'in ötesinden Gidyon'a getirdiler."]],8:[["1","Efraimliler ona, “Neden bize böyle davrandın da Midyan'la savaşmaya gittiğinde bizi çağırmadın?” dediler. Onu sert bir şekilde azarladılar."],["2","Onlara şöyle dedi: “Sizinle karşılaştırıldığında benim şimdi yaptığım nedir? Efraim'in üzümlerinin toplanması Aviezer'in bağbozumundan daha iyi değil mi?"],["3","Tanrı Midyan'ın, Orev'in ve Zeev'in beylerini sizin elinize teslim etti. Sizinle karşılaştırıldığında ben ne yapabilirdim ki?” Sonra bunu söyleyince ona olan öfkeleri yatıştı."],["4","Gidyon Yarden'e geldi, yanında bulunan üç yüz adamla birlikte bitkindi ama yine de kovalayarak geçti."],["5","Sukkotlular'a şöyle dedi: “Lütfen arkamdan gelenlere ekmek verin; çünkü bitkinler; ben de Midyan kralları Zevah'ı ve Salmunna'yı kovalıyorum.”"],["6","Sukkot beyleri, “Orduna ekmek vermemiz için Zevah ve Salmunna'nın elleri şimdi senin elinde mi?” dediler."],["7","Gidyon şöyle dedi: “Bu nedenle Yahve Zevah'ı ve Salmunna'yı elime verdiğinde, o zaman etini çöldeki dikenlerle ve çalılarla yaracağım.”"],["8","Oraya Penuel'in yanına çıktı ve onlarla aynı şekilde konuştu; ve Penuel'in adamları ona Sukkot'un adamları gibi yanıt verdiler."],["9","Penuel adamlarıyla da konuşarak, “Esenlik içinde geri döndüğümde bu kuleyi yıkacağım” dedi."],["10","Zevah ile Salmunna Karkor'daydı ve kendileriyle birlikte yaklaşık on beş bin kişilik orduları vardı; bunların hepsi doğu çocuklarının ordusundan arta kalanlardı; çünkü kılıç çeken yüz yirmi bin adam düşmüştü."],["11","Gidyon Nova ile Yogbeha'nın doğusunda çadırlarda yaşayanların yolundan çıkıp orduyu vurdu; çünkü ordu kendini güvende hissetti."],["12","Zevah ile Salmunna kaçtılar, o da onları kovaladı. Midyan'ın iki kralı Zevah ve Salmunna'yı tuttu ve bütün orduyu karıştırdı."],["13","Yoaş oğlu Gidyon, Heres Yokuşu'ndan savaştan döndü."],["14","Sukkot adamlarından bir genci yakalayıp ona sordu, o da Sukkot beylerini ve ihtiyarları olan yetmiş yedi kişiyi tarif etti."],["15","Sukkot adamlarına gelip şöyle dedi: “'Zevah ve Salmunna'nın elleri şimdi senin elinde mi ki, yorgun adamlarınıza ekmek verelim' diye benimle alay ettiğiniz Zevah ve Salmunna'ya bakın?"],["16","Kentin ihtiyarlarını, çöldeki dikenleri ve çalıları alıp onlarla Sukkot adamlarına ders verdi."],["17","Penuel Kulesi'ni yıktı ve kent halkını öldürdü."],["18","Sonra Zevah ve Salmunna'ya, “Tavor'da öldürdüğünüz adamlar nasıl insanlardı?” diye sordu. Şöyle yanıt verdiler: “Onlar da senin gibiydi. Hepsi bir kralın çocuklarına benziyordu.”"],["19","“Onlar benim kardeşlerim, annemin oğullarıydı” dedi. “Yahve'nin hakkı için, eğer onları sağ bırakmış olsaydınız, sizi öldürmezdim.”"],["20","İlk oğlu Yeter'e, “Kalk, onları öldür!” dedi. Ama genç kılıcını çekmedi; çünkü korkuyordu, çünkü henüz gençti."],["21","Bunun üzerine Zevah ile Salmunna şöyle dediler: “Sen kalk da üzerimize in; çünkü adam nasılsa, gücü de öyledir.” Gidyon kalkıp Zevah'la Salmunna'yı öldürdü ve develerinin boyunlarındaki hilâlleri aldı."],["22","Bunun üzerine İsrael halkı Gidyon'a şöyle dediler: “Hem sen, hem oğlun, hem de oğlunun oğlu bize hükmetsin; çünkü bizi Midyan'ın elinden kurtardın.”"],["23","Gidyon onlara şöyle dedi: “Ben size hükmetmeyeceğim, oğlum da size hükmetmeyecek. Yahve size hükmedecek.”"],["24","Gidyon onlara şöyle dedi: “Sizden bir dileğim var: Her biriniz ganimetinin küpelerini bana versin.” (İşmaelliler oldukları için altın küpeleri vardı.)"],["25","Onlar, “Onlara seve seve veririz” dediler. Bir giysi serdiler ve herkes ganimetinin küpelerini onun içine attı."],["26","İstediği altın küpelerin ağırlığı, hilâller, kolyeler, Midyan krallarının üzerindeki mor giysilerden başka ve develerinin boyunlarındaki zincirlerden başka bin yedi yüz şekel altındı."],["27","Gidyon ondan bir efod yapıp onu kendi kenti Ofra'ya koydu. Sonra bütün İsrael orada onunla fahişelik etti; Gidyon ile evi için de bir tuzak oldu."],["28","Böylece Midyan, İsrael çocuklarının önünde boyun eğdirildi; onlar artık başlarını kaldırmadılar. Gidyon'un günlerinde ülke kırk yıl rahat etti."],["29","Yoaş oğlu Yerubbaal gidip kendi evinde yaşadı."],["30","Gidyon'un kendi bedeninden yetmiş oğlu oldu; çünkü çok karısı vardı."],["31","Şekem'deki cariyesi de ona bir oğul doğurdu ve ona Avimelek adını verdi."],["32","Yoaş oğlu Gidyon güzel ihtiyarlıkta öldü ve Aviezerliler'in Ofra Kenti'nde babası Yoaş'ın mezarına gömüldü."],["33","Gidyon ölür ölmez İsrael'in çocukları tekrar dönüp Baallar'ın ardından fahişelik ettiler, Baal Berit'i de kendilerine ilâh yaptılar."],["34","İsrael'in çocukları, kendilerini her yandaki düşmanlarının elinden kurtaran Tanrıları Yahve'yi hatırlamadılar;"],["35","Yerubbaal'ın evine, yani Gidyon'a da, onun İsrael'e gösterdiği bütün iyiliğe göre iyilik göstermediler."]],9:[["1","Yerubbaal oğlu Avimelek, Şekem'e annesinin kardeşlerinin yanına gitti ve onlarla ve annesinin babasının evindeki bütün aile üyeleriyle konuştu ve şöyle dedi:"],["2","“Lütfen bütün Şekem halkının kulağına konuşun, 'Sizin için hangisi daha iyi, Yerubbaal'ın yetmiş kişilik bütün oğullarının size hükmetmesi mi, yoksa bir insanın mi size hükmetmesi?' Benim sizin kemiğiniz ve etiniz olduğumu da hatırlayın.”"],["3","Annesinin kardeşleri onun hakkında bütün bu sözleri Şekem halkının kulağına söylediler. Onların yürekleri Avimelek'in ardınca gitme eğilimindeydi; çünkü “O bizim kardeşimizdir” dediler."],["4","Baal Berit'in evinden ona yetmiş gümüş verdiler; Avimelek bu parayla kendisini izleyen faydasız ve pervasız adamları tuttu."],["5","Ofra'da babasının evine gitti ve kardeşlerini, Yerubbaal'ın yetmiş oğlunu, bir taş üzerinde öldürdü; ancak Yerubbaal'ın en küçük oğlu Yotam saklandığı için sağ kaldı."],["6","Bütün Şekemliler, Millo'nun evinin tümüyle birlikte toplandılar ve gidip Şekem'deki dikili taş meşesinin yanında Avimelek'i kral yaptılar."],["7","Bunu Yotam'a söylediklerinde o gidip Gerizim Dağı'nın tepesinde durdu, sesini yükseltip bağırdı ve onlara şöyle dedi: “Ey Şekemliler, beni dinleyin de, Tanrı sizi duysun."],["8","Ağaçlar kendilerine bir kral atamak için yola çıktılar. Zeytin ağacına, 'Bize hükümdarlık yap' dediler.”"],["9","“Ama zeytin ağacı onlara şöyle dedi: 'Benim aracılığımla Tanrı'yı ve insanı onurlandırdıkları yağımı üretmeyi bırakıp, ağaçların üzerinde ileri geri sallanmaya mı gideyim?'”"],["10","“Ağaçlar incir ağacına, 'Gel ve üzerimize hükümdar ol' dedi.”"],["11","“Ama incir ağacı onlara şöyle dedi: 'Tatlılığımı ve güzel meyvemi bırakıp da ağaçların üzerinde ileri geri sallanmaya mı gideyim?'”"],["12","“Ağaçlar asmaya, 'Gel de üzerimize hükümdar ol' dedi.”"],["13","“Asma onlara şöyle dedi: 'Tanrı'yı ve insanları neşelendiren yeni şarabımı bırakıp da ağaçların üzerinde ileri geri sallanmaya mı gideyim?'”"],["14","“Sonra bütün ağaçlar kara çalıya, 'Gel de üzerimize hükümdar ol' dediler.”"],["15","“Kara çalı ağaçlara şöyle dedi: 'Eğer gerçekten beni üzerinize kral olarak meshederseniz, o zaman gelin gölgeme sığının; yoksa kara çalıdan ateş çıksın ve Lübnan'ın sedir ağaçlarını yiyip bitirsin.'”"],["16","“Şimdi, eğer Avimelek'i kral yaparak doğru ve haklı olarak davrandıysanız ve Yerubbaal'a ve onun evine karşı iyilikle davrandıysanız, onun ellerinin hak ettiğine göre karşılık verdiyseniz"],["17","(çünkü babam sizin için savaştı, canını tehlikeye attı ve sizi Midyan'ın elinden kurtardı;"],["18","siz de bugün babamın evine karşı ayaklandınız ve onun oğullarını, yetmiş kişiyi bir taş üzerinde öldürdünüz ve cariyesinin oğlu Avimelek'i Şekemliler üzerine kral yaptınız; çünkü o sizin kardeşinizdir);"],["19","eğer bugün Yerubbaal'a ve onun evine doğru ve haklı olarak davrandıysanız, Avimelek'le sevinin, o da sizinle sevinsin;"],["20","ama öyle değilse, Avimelek'ten ateş çıksın ve Şekemliler'i ve Millo evini yiyip bitirsin; Şekemliler'den ve Millo evinden de ateş çıksın ve Avimelek'i yiyip bitirsin.”"],["21","Yotam kardeşi Avimelek'ten korktuğu için kaçıp Beer'e gitti ve orada yaşadı."],["22","Avimelek üç yıl İsrael'e beylik yaptı."],["23","Bunun üzerine Tanrı, Avimelek'le Şekemliler'in arasına kötü bir ruh gönderdi,"],["24","Yerubbaal'ın yetmiş oğluna yapılan zorbalık onun üzerine gelsin ve onların kanı, onları öldüren kardeşleri Avimelek'in üzerine ve kardeşlerini öldürmek için onun ellerini güçlendiren Şekemliler'in üzerine dökülsün diye, Şekemliler Avimelek'e hainlik ettiler."],["25","Şekemliler ona karşı dağların başlarında pusu kurdular ve o yoldan yanlarından geçenlerin hepsini soydular; Avimelek'e de bundan söz edildi."],["26","Ebed oğlu Gaal kardeşleriyle birlikte gelip Şekem'e gitti; ve Şekemliler ona güvendiler."],["27","Kıra çıktılar, bağlarını topladılar, üzümleri çiğnediler, kutlama yaptılar, ilâhlarının evine girdiler, yiyip içtiler ve Avimelek'e lanet ettiler."],["28","Ebed oğlu Gaal, “Avimelek ve Şekem kimdir ki, ona hizmet edelim?” dedi. “Yerubbaal'ın oğlu değil mi o? Zevul onun görevlisi değil mi? Şekem'in babası Hamor'un adamlarına hizmet edin, ama biz neden ona hizmet edelim?"],["29","Keşke bu halk benim elimin altında olsaydı! O zaman Avimelek'i ortadan kaldırırdım.” Avimelek'e, “Ordunu çoğalt da dışarı çık” dedi."],["30","Kentin yöneticisi Zevul, Ebed oğlu Gaal'ın sözlerini duyunca öfkesi alevlendi."],["31","Avimelek'e kurnazca ulaklar göndererek şöyle dedi: “İşte, Ebed oğlu Gaal ve kardeşleri Şekem'e geldiler; ve işte, kenti sana karşı kışkırtıyorlar."],["32","Şimdi sen ve yanındaki halk geceleyin yola çıkın ve kırda pusuya yatın."],["33","Sabah güneş doğar doğmaz erkenden kalkıp kente hücum edeceksiniz. İşte, o ve onunla birlikte olan halk size karşı çıktıklarında, onlara elinden geleni yaparsın.”"],["34","Avimelek ve yanındaki halk geceleyin kalktılar ve dört bölük halinde Şekem'e karşı pusuda yattılar."],["35","Ebed oğlu Gaal dışarı çıkıp kentin kapısının girişinde durdu. Avimelek ve yanındaki halk pusudan kalktı."],["36","Gaal halkı görünce Zevul'a, “İşte, insanlar dağların başlarından iniyor” dedi. Zevul ona, “Dağların gölgelerini sanki insanmış gibi görüyorsun” dedi."],["37","Gaal tekrar konuştu ve şöyle dedi: “İşte, insanlar diyarın ortasından aşağıya iniyor ve bir bölük de Meonenim Meşesi yolundan geliyor.”"],["38","Bunun üzerine Zevul ona şöyle dedi: “'Avimelek kimdir ki, ona hizmet edelim' diyen ağzın şimdi nerede? Bu küçümsediğin halk değil mi? Lütfen şimdi çık da onlarla savaş.”"],["39","Gaal, Şekemliler'in önünden çıkıp Avimelek'le savaştı."],["40","Avimelek onu kovaladı, o da onun önünden kaçtı; çok kişi kapının girişine kadar yaralı düştü."],["41","Avimelek Arumah'ta yaşıyordu; ve Zevul, Şekem'de oturmasınlar diye Gaal'la kardeşlerini kovdu."],["42","Ertesi gün halk kıra çıktı; Avimelek'e de söylediler."],["43","Halkı alıp üç bölüğe ayırdı ve kırda pusuya yattı; ve baktı ve halkın kentten çıktığını gördü. Bunun üzerine onlara karşı kalkıp onları vurdu."],["44","Avimelek ve beraberindekiler ileri hücum ettiler ve kent kapısının girişinde durdular; iki bölük de kırda olanların üzerine hücum edip onları vurdular."],["45","Avimelek bütün gün kente karşı savaştı; ve kenti aldı ve içindeki insanları öldürdü. Kenti yerle bir etti ve üzerine tuz saçtı."],["46","Şekem Kulesi'ndeki bütün insanlar bunu duyunca Elberit Evi'nin kalesine girdiler."],["47","Avimelek'e Şekem Kulesi'ndeki bütün insanların toplandığı söylendi."],["48","Avimelek ve yanındaki halkın tümü Salmon Dağı'na çıktı; ve Avimelek eline bir balta aldı, ve ağaçlardan bir dal kesti, ve onu kaldırıp omuzu üzerine koydu. Sonra yanında olan halka, “Benim ne yaptığımı gördünüz, acele edin, siz de benim gibi yapın!” dedi."],["49","Bütün halk da aynı şekilde onun dalını kesti, Avimelek'in ardından gitti ve onları kalenin dibine koydu ve kaleyi üzerlerine ateşe verdi; böylece Şekem Kulesi'ndeki bütün halk, kadın ve erkek olmak üzere, bin kadar kişi öldü."],["50","Bunun üzerine Avimelek Teves'e gitti, Teves'e karşı ordugâh kurdu ve kenti aldı."],["51","Ama kentin içinde güçlü bir kule vardı; kentin bütün kadın ve erkekleri oraya kaçıp kendilerini içeri kapattılar ve kulenin damına çıktılar."],["52","Avimelek kuleye gelip ona karşı savaştı ve onu ateşe vermek için kulenin kapısına yaklaştı."],["53","Bir kadın Avimelek'in başına değirmenin üst taşını attı ve kafatasını kırdı."],["54","Sonra aceleyle silah taşıyıcısı genç adamı çağırdı ve ona şöyle dedi: “Kılıcını çek ve beni öldür ki, insanlar benim için 'Onu bir kadın öldürdü' demesin. Genç adamı kılıcını ona sapladı ve o öldü.”"],["55","İsraelliler Avimelek'in öldüğünü görünce hepsi kendi yerlerine gittiler."],["56","Böylece Tanrı, Avimelek'in yetmiş kardeşini öldürerek babasına yaptığı kötülüğün karşılığını böyle ödedi;"],["57","ve Tanrı Şekemliler'in bütün kötülüklerinin karşılığını onların başlarına ödedi; Yerubbaal oğlu Yotam'ın da laneti üzerlerine geldi."]],10:[["1","Avimelek'ten sonra, İsrael'i kurtarmak için İssakar'dan biri olan Dodo oğlu, Puah oğlu Tola, ortaya çıktı. Efraim'in dağlık bölgesinde Şamir'de yaşıyordu."],["2","İsrael'e yirmi üç yıl hükmetti ve öldü ve Şamir'e gömüldü."],["3","Ondan sonra Giladlı Yair ortaya çıktı. İsrael'e yirmi iki yıl hükmetti."],["4","Onun sıpaya binen otuz oğlu vardı. Gilad diyarında olup bugüne dek Havvot Yair denilen otuz kentleri vardı."],["5","Yair öldü ve Kamon'a gömüldü."],["6","İsrael'in çocukları yine Yahve'nin gözünde kötü olanı yaptılar ve Baallar'a, Aştoretler'e, Aram ilâhlarına, Sayda ilâhlarına, Moav ilâhlarına, Ammon çocuklarının ilâhlarına ve Filistliler'in ilâhlarına hizmet ettiler. Yahve'yi bıraktılar ve O'na hizmet etmediler."],["7","Yahve’nin öfkesi İsrael'e karşı alevlendi ve onları Filistliler'in eline ve Ammon çocuklarının eline sattı."],["8","O yıl İsrael'in çocuklarını sıkıntıya sokup ezdiler. On sekiz yıl boyunca, Gilad'da bulunan Amorlular'ın ülkesinde, Yarden'in ötesinde olan bütün İsrael çocuklarını ezdiler."],["9","Ammon'un çocukları, Yahuda'ya ve Benyamin'e ve Efraim'in evine karşı savaşmak için Yarden'den geçti, bu yüzden İsrael çok sıkıntılıydı."],["10","İsrael'in çocukları Yahve'ye feryat edip “Tanrımızı bırakıp Baallar'a hizmet ettiğimiz için sana karşı günah işledik” dediler."],["11","Yahve İsrael'in çocuklarına, “Sizi Mısırlılar'dan ve Amorlular'dan, Ammon'un çocuklarından ve Filistliler'den kurtarmadım mı?"],["12","Saydalılar ve Amalekliler ve Maonlular sizi ezdi; ve bana feryat ettiniz, ben de sizi onların elinden kurtardım."],["13","Yine de beni bıraktınız ve başka ilâhlara hizmet ettiniz. Bu yüzden sizi bir daha kurtarmayacağım."],["14","Gidin de seçmiş olduğunuz ilâhlara feryat edin. Sıkıntı zamanınızda onlar sizi kurtarsın!” dedi."],["15","İsrael'in çocukları Yahve'ye, “Günah işledik! Senin gözünde iyi görünen her ne ise bize öyle yap; Lütfen, bizi yalnız bugün kurtar.”"],["16","Yabancı ilâhları aralarından uzaklaştırdılar ve Yahve'ye hizmet ettiler; O'nun Ruhu da İsrael'in sefaleti için kederlendi."],["17","Ammon'un çocukları toplanıp ve Gilad'da ordugâh kurdular. İsrael'in çocukları da toplandılar ve Mizpah'da ordugâh kurdular."],["18","Gilad beyleri, birbirlerine dediler, “Ammon çocuklarına karşı savaşmaya başlayacak olan adam kimdir? Gilad'ın tüm sakinleri üzerinde o baş olacaktır.”"]],11:[["1","Giladlı Yeftah cesur bir yiğitti. Bir fahişenin oğluydu. Yeftah'ın babası Gilad'dı."],["2","Gilad'ın karısı ona oğullar doğurdu. Karısının oğulları büyüyünce Yeftah'ı dışarı çıkarıp ona, “Babamızın evinde mirasçı olmayacaksın, çünkü sen başka bir kadının oğlusun” dediler."],["3","Bunun üzerine Yeftah kardeşlerinden kaçıp Tob diyarına yerleşti. Kanun kaçakları Yeftah'a katıldı ve onunla birlikte çıkarlardı."],["4","Bir süre sonra Ammonlular İsrael'e savaş açtılar."],["5","Ammon'un çocukları İsrael'e karşı savaş açtığında Gilad ihtiyarları Tob ülkesinden Yeftah'ı getirmek için yola çıktılar."],["6","Yeftah'a, “Gel, reisimiz ol, Ammon'un çocuklarıyla savaşalım” dediler."],["7","Yeftah Gilad ihtiyarlarına şöyle dedi: “Benden nefret edip beni babamın evinden kovmadınız mı? Şimdi sıkıntı içindeyken neden bana geldiniz?”"],["8","Gilad ihtiyarları Yeftah'a şöyle dediler: “Bu nedenle bizimle gelip Ammon'un çocuklarıyla savaşasın diye şimdi sana döndük. Gilad'ın bütün sakinleri üzerinde başımız olacaksın.”"],["9","Yeftah Gilad ihtiyarlarına şöyle dedi: “Eğer Ammon'un çocuklarıyla savaşmak için beni yeniden eve götürürseniz ve Yahve onları benim önümde teslim ederse, ben sizin başınız olacak mıyım?”"],["10","Gilad ihtiyarları Yeftah'a şöyle dediler: “Yahve aramızda tanık olacaktır. Kesinlikle senin söylediklerini yapacağız.”"],["11","Bunun üzerine Yeftah Gilad'ın ihtiyarlarıyla birlikte gitti ve halk onu kendilerine baş ve reis yaptı. Yeftah bütün sözlerini Mitspa'da Yahve'nin önünde söyledi."],["12","Yeftah, Ammon çocuklarının Kralı'na ulaklar göndererek şöyle dedi: “Ülkemle savaşmak için bana geldin de benimle ne işin var ki?”"],["13","Ammon'un çocuklarının Kralı Yeftah'ın ulaklarına şöyle yanıt verdi: “Çünkü İsrael Mısır'dan çıktığında Arnon'dan Yabbok'a ve Yarden'e kadar olan benim diyarımı aldı. Bu nedenle şimdi bu bölgeyi barışçıl bir şekilde geri ver.”"],["14","Yeftah Ammon'un çocuklarının Kralı'na yine ulaklar gönderdi;"],["15","ve ona şöyle dedi: “Yeftah diyor ki: İsrael Moav ülkesini ya da Ammon'un çocuklarının ülkesini almadı;"],["16","ama Mısır'dan çıktıkları zaman İsrael çölden Kızıldeniz'e kadar gitti ve Kadeş'e geldi,"],["17","sonra İsrael Edom Kralı'na ulaklar göndererek, 'Lütfen senin ülkenin içinden geçeyim' dedi; ama Edom Kralı dinlemedi. Aynı şekilde Moav Kralı'na da gönderdi ama o reddetti; böylece İsrael Kadeş'te kaldı."],["18","Sonra çölden geçip Edom ülkesinin ve Moav ülkesinin çevresini dolaştılar, Moav ülkesinin doğu yakasına geldiler ve Arnon Nehri'nin karşı yakasında konakladılar; ama Moav sınırı içine girmediler; çünkü Arnon Moav sınırıydı."],["19","İsrael, Amorlular'ın Kralı, Heşbon Kralı Sihon'a ulaklar gönderdi; İsrael ona, 'Lütfen senin diyarının içinden yerimize geçelim' dedi."],["20","Ama Sihon, İsrael'in kendi sınırından geçip gideceğine güvenmedi; ama Sihon bütün halkını bir araya toplayıp Yahats'da ordugâh kurdu ve İsrael'e karşı savaştı."],["21","İsrael'in Tanrısı Yahve Sihon'u ve bütün halkını İsrael'in eline teslim etti ve onlar da onları vurdu. Böylece İsrael, o ülkede oturan Amorlular'ın bütün diyarını mülk edindi."],["22","Arnon'dan Yabbok'a kadar, çölden Yarden'e kadar Amorlular'ın bütün sınırını mülk edindiler."],["23","Şimdi İsrael'in Tanrısı Yahve, Amorlular'ı kendi halkı İsrael'in önünden mülkünden etti; sen mi onları mülk edineceksin?"],["24","İlâhın Kemoş'un sana mülk olarak verdiğini sen mülk edinmeyecek misin? Böylece Tanrımız Yahve'nin önümüzden mülksüz ettiklerini, biz onları mülk edineceğiz."],["25","Şimdi sen Moav Kralı Sippor oğlu Balak'tan daha mı iyisin? O hiç İsrael'e karşı çekişti mi ya da onlara karşı hiç savaştı mı?"],["26","İsrael, Heşbon'da ve kasabalarında, Aroer'de ve kasabalarında ve Arnon yanında olan bütün kentlerde üç yüz yıl yaşadı. Neden bu süre içinde onları kurtarmadınız?"],["27","Bu nedenle ben sana karşı günah işlemedim, ama sen bana karşı savaşarak bana haksızlık ediyorsun. Bugün Yargıç olan Yahve İsrael'in çocukları ile Ammon'un çocukları arasında hükmetsin.”"],["28","Ancak Ammon çocuklarının Kralı Yeftah'ın kendisine gönderdiği sözleri dinlemedi."],["29","Bunun üzerine Yahve'nin Ruhu Yeftah'ın üzerine indi ve Gilad'dan ve Manaşşe'den geçti, Gilad'daki Mitspa'dan geçti ve Gilad'daki Mitspa'dan Ammon'un çocuklarına geçti."],["30","Yeftah, Yahve'ye bir adak adadı ve şöyle dedi: “Eğer gerçekten Ammon çocuklarını elime verirsen,"],["31","o zaman öyle olacak ki, ben Ammon'un çocuklarından esenlik içinde döndüğümde beni karşılamak için evimin kapılarından çıkan Yahve'nin olacaktır ve onu yakmalık sunu olarak sunacağım.''"],["32","Bunun üzerine Yeftah, Ammonlular'la savaşmak üzere Ammonlular'ın yanına geçti; ve Yahve onları onun eline teslim etti."],["33","Aroer'den Minnit'e varıncaya dek yirmi kenti ve Abelkeramim'e kadar çok büyük bir kıyımla onları vurdu. Böylece Ammon'un çocukları İsrael'in çocukları önünde boyun eğdirildi."],["34","Yeftah Mizpah'a, kendi evine geldi; ve işte, kızı onunla tef ve danslarla buluşmaya çıktı. O onun tek çocuğuydu. Onun dışında ne oğlu ne de kızı vardı."],["35","Onu görünce giysilerini yırttı ve “Eyvah, kızım! Beni fena yıktın ve beni sıkıntıya sokanlardan birisi oldun; çünkü ağzımı Yahve'ye açtım ve geri dönemem. ”"],["36","Kız ona, “Babam, ağzını Yahve'ye açtın; bana ağzından çıkmış olana göre yap, çünkü Yahve düşmanlarından, Ammon'un çocuklarından senin için öç aldı. ”"],["37","Babasına, “Bu şey benim için yapılsın. Beni iki ay yalnız bırak, ayrılıp dağlara ineyim, arkadaşlarımla birlikte el değmemiş kızlığıma ağlayayım.”"],["38","“Git” dedi. Onu iki aylığına gönderdi; arkadaşlarıyla birlikte gitti ve dağlarda el değmemiş kızlığına ağladı."],["39","İki ayın sonunda, babasına döndü, adamış olduğu anda göre ona yaptı. El değmemiş bir kızdı. İsrael'de bir gelenek oldu,"],["40","İsrael kızları yılda dört gün Giladlı Yeftah'ın kızını anmak için yıldan yıla giderler."]],12:[["1","Efraimliler toplanıp kuzeye doğru geçtiler ve Yeftah'a dediler: “Neden Ammon'un çocuklarıyla savaşmak için geçtin de seninle birlikte gitmemiz için bizi çağırmadın? Çepeçevre senin üzerine evini ateşle yakacağız!”"],["2","Yeftah onlara şöyle dedi: “Ben ve halkım Ammon'un çocuklarıyla büyük bir çekişme içindeydik; sizi çağırdığımda da beni onların elinden kurtarmadınız."],["3","Beni kurtarmadığınızı görünce canımı elime aldım, Ammon'un çocuklarına karşı üzerlerinden geçtim. Yahve onları elime teslim etti. O halde neden bugün bana karşı savaşmak için yanıma çıktınız?”"],["4","Bunun üzerine Yeftah Gilad'ın bütün adamlarını toplayıp Efraim'le savaştı. Giladlılar Efraim'i vurdular, çünkü şöyle dediler: “Ey Giladlılar, Efraim'in ortasında ve Manaşşe'nin ortasında, siz Efraim'in kaçaklarısınız.”"],["5","Giladlılar Efraimliler'e karşı Yarden'in geçitlerini aldılar. Efraimli bir kaçak, “Geçeyim” dediğinde, Giladlılar ona, “Sen Efraimli misin?” derlerdi. “Hayır” derse;"],["6","o zaman ona, “Şimdi 'Şibbolet' de” derlerdi, o da “Sibbolet” derdi; çünkü onu doğru söyleyemezdi, sonra onu Yarden'in geçitlerinde yakalayıp öldürürlerdi. O sırada kırk iki bin Efraimli düştü."],["7","Yeftah altı yıl İsrael'e hükmetti. Sonra Giladlı Yeftah öldü ve Gilad kentlerinde gömüldü."],["8","Ondan sonra Beytlehemli İvsan İsrael'e hükmetti."],["9","Otuz oğlu vardı. Otuz kızını kendi boyunun dışına gönderdi ve oğulları için de kendi boyunun dışından otuz kız getirdi. İsrael'e yedi yıl hükmetti."],["10","İvsan öldü ve Beytlehem'de gömüldü."],["11","Ondan sonra İsrael'e Zevulunlu Elon hükmetti; ve on yıl İsrael'e hükmetti."],["12","Zevulunlu Elon öldü ve Zevulun diyarındaki Ayyalon'da gömüldü."],["13","Ondan sonra İsrael'e Piratonlu Hillel oğlu Avdon hükmetti."],["14","Onun yetmiş sıpaya binen kırk oğlu ve otuz torunu vardı. İsrael'e sekiz yıl hükmetti."],["15","Piratonlu Hillel oğlu Avdon öldü ve Amalekliler'in dağlık bölgesindeki Efraim ülkesindeki Piraton'da gömüldü."]],13:[["1","İsrael'in çocukları yine Yahve'nin gözünde kötü olanı yaptı; ve Yahve onları kırk yıl Filistliler'in eline teslim etti."],["2","Danlılar'dan Soralı bir adam vardı; adı Manoah'tı; karısı ise kısır ve çocuksuzdu."],["3","Yahve'nin meleği kadına görünüp şöyle dedi: “Bak, sen kısır ve çocuksuzsun; ama gebe kalacaksın ve bir oğul doğuracaksın."],["4","Bu nedenle şimdi lütfen, şarap ve ağır içki içmekten sakın ve kirli bir şey de yeme;"],["5","çünkü işte, gebe kalacaksın ve bir oğul doğuracaksın. Başına ustura değmeyecek; çünkü çocuk, rahimden Tanrı'nın Adanmışı olacaktır. O, İsrael'i Filistliler'in elinden kurtarmaya başlayacak.”"],["6","Sonra kadın gelip kocasına şöyle dedi: “Bana bir Tanrı adamı geldi; yüzü Tanrı'nın meleğinin yüzü gibiydi, çok heybetliydi. Ona nereli olduğunu sormadım, bana adını da söylemedi;"],["7","ama bana dedi: 'İşte gebe kalacaksın ve bir oğul doğuracaksın; artık şarap ve ağır içki içme. Kirli bir şey yeme; çünkü çocuk, ana rahminden öleceği güne dek Tanrı'nın Adanmışı olacaktır.'”"],["8","Bunun üzerine Manoah Yahve'ye yalvarıp şöyle dedi: “Ey Efendim, lütfen gönderdiğin Tanrı adamı bize yine gelsin ve doğacak çocuğa ne yapmamız gerektiğini bize öğretsin.”"],["9","Tanrı, Manoah'ın sesini duydu ve Tanrı'nın meleği, kadın tarlada otururken ona yeniden geldi; ama kocası Manoah onun yanında değildi."],["10","Kadın aceleyle koşup kocasına şöyle dedi: “İşte, o gün yanıma gelen adam bana göründü.”"],["11","Manoah kalkıp karısının ardından gitti ve adamın yanına gelerek, “Karımla konuşan adam sen misin?” dedi. “Ben'im” dedi."],["12","Manoah şöyle dedi: “Şimdi sözlerin gerçekleşsin. Çocuğun hayatının yönü ve görevi ne olacak?”"],["13","Yahve'nin meleği Manoah'a şöyle dedi: “Kadın ona söylediğim her şeyden sakınsın."],["14","Asmadan çıkan hiçbir şeyi yemesin, şarap ya da ağır içki içmesin, kirli bir şey de yemesin. Ona buyurduklarımın hepsini tutsun.”"],["15","Manoah, Yahve'nin meleğine, “Lütfen bizimle kal, sana bir oğlak hazırlayalım” dedi."],["16","Yahve'nin meleği Manoah'a şöyle dedi: “Beni alıkoysan da, senin ekmeğini yemeyeceğim. Yakmalık sunu hazırlayacaksan onu Yahve'ye sunmalısın.” Çünkü Manoah O'nun Yahve'nin meleği olduğunu bilmiyordu."],["17","Manoah, Yahve'nin meleğine, “Adın nedir, ta ki, sözlerin gerçekleştiğinde seni onurlandıralım?” dedi."],["18","Yahve'nin meleği ona, “Adım hakkında neden soruyorsun? Çünkü onu akıl almaz.” dedi."],["19","Bunun üzerine Manoah oğlağı ekmek sunusuyla birlikte alıp kayanın üzerinde Yahve'ye sundu. Sonra Manoah ve karısı izlerken melek şaşılacak bir şey yaptı."],["20","Sunaktaki alev gökyüzüne doğru yükselirken, Yahve'nin meleği sunağın aleviyle yükseldi. Manoah ve karısı izlerken; yüzüstü yere kapandılar."],["21","Ancak Yahve'nin meleği bir daha Manoah ya da karısına görünmedi. Yahve'nin meleği olduğunu Manoah o zaman bildi."],["22","Manoah karısına, “Kesin öleceğiz, çünkü Tanrı'yı gördük” dedi."],["23","Ama karısı ona şöyle dedi: “Eğer Yahve bizi öldürmek isteseydi, elimizden yakmalık sunuyu ve ekmek sunusunu almazdı, bütün bu şeyleri bize göstermezdi, ya da bize bu zamanda buna benzer şeyler bildirmezdi.”"],["24","Kadın bir oğul doğurdu ve ona Şimşon adını verdi. Çocuk büyüdü ve Yahve onu kutsadı."],["25","Yahve'nin Ruhu onu Sora ile Eştaol arasındaki Mahane Dan'da harekete geçirmeye başladı."]],14:[["1","Şimşon Timna'ya gitti ve Timna'da Filistliler'in kızlarından bir kadın gördü."],["2","Çıkıp babası ve annesine şöyle dedi: “Timna'da Filistliler'in kızlarından bir kadın gördüm. Şimdi onu karım olarak bana alın.”"],["3","Bunun üzerine babasıyla annesi ona, “Kardeşlerinin kızları arasında ya da bütün halkım arasında bir kadın yok mu ki, sünnetsiz Filistliler'den kadın almaya gidiyorsun?” dediler. Şimşon babasına, “Onu bana alın, çünkü o benin çok hoşuma gidiyor” dedi."],["4","Ama annesiyle babası bunun Yahve'den olduğunu bilmiyordu; çünkü Filistliler'e karşı bir fırsat arıyordu. O sıralarda İsrael üzerinde Filistliler hüküm sürüyordu."],["5","Bunun üzerine Şimşon, babası ve annesiyle birlikte Timna'ya inip Timna'nın bağlarına geldi; ve işte, genç bir aslan ona kükredi."],["6","Yahve'nin Ruhu güçlü bir şekilde onun üzerine geldi, bir oğlağı çıplak ellerle parçalar gibi onu parçaladı, ama yaptığını babasına ya da annesine bildirmedi."],["7","Aşağıya inip kadınla konuştu; kadın Şimşon'un hoşuna gitti."],["8","Bir süre sonra onu almak için geri döndü ve aslanın leşini görmeye gitti; ve işte, aslanın vücudunda bir arı sürüsü ve bal vardı."],["9","Onu eline aldı ve giderken yiyerek gitti. Babasının ve annesinin yanına geldi onlara da verdi, onlar da yediler ama balı aslanın leşinden çıkardığını onlara söylemedi."],["10","Babası kadının yanına indi; ve Şimşon orada bir ziyafet verdi; çünkü gençler böyle yaparlardı."],["11","O'nu görünce yanında olsun diye otuz arkadaş getirdiler."],["12","Şimşon onlara şöyle dedi: “Şimdi size bir bilmece söyleyeyim. Yanıtını ziyafetin yedi günü içinde bulup bana söyleyebilirseniz, o zaman size otuz keten giysi ve otuz yedek giysi vereceğim;"],["13","ama yanıtı bana söyleyemezseniz, bana otuz keten giysi ve otuz yedek giysi vereceksiniz.” Ona, “Bize bilmeceni söyle de duyalım” dediler."],["14","Onlara şöyle dedi: “Yiyenden yiyecek çıktı. Güçlüden tatlılık çıktı.” Üç gün içinde bilmeceyi açıklayamadılar."],["15","Yedinci gün Şimşon'un karısına şöyle dediler: “Kocanı kandır da bilmeceyi bize açıklasın, yoksa seni ve babanın evini yakarız. Bizi fakirleştirmek için mi çağırdınız? Öyle değil mi?”"],["16","Şimşon'un karısı onun önünde ağlayarak şöyle dedi: “Benden yalnızca nefret ediyorsun, beni sevmiyorsun. Halkımın çocuklarına bir bilmece söyledin ama bana bildirmedin.” Ona, “İşte, bunu ne babama ne de anneme söylemedim, öyleyse sana neden söyleyeyim?” dedi."],["17","Ziyafet sürerken, yedi gün onun önünde ağladı; ve yedinci gün, ona çok baskı yaptığı için bunu ona söyledi; o da bilmeceyi halkının çocuklarına anlattı."],["18","Yedinci gün güneş batmadan önce kentin adamları ona, “Baldan daha tatlı ne olabilir?” dediler. “Aslandan daha güçlü olan nedir?” Onlara, “Eğer düvemle çift sürmüş olmasaydınız, bilmecemi çözemezdiniz” dedi."],["19","Yahve'nin Ruhu güçlü bir şekilde onun üzerine geldi ve Aşkelon'a inerek onlardan otuz kişiyi vurdu. Yağmalarını aldı, sonra bilmeceyi bildirenlere yedek kıyafetleri verdi. Öfkesi alevlendi ve babasının evine gitti."],["20","Ama Şimşon'un karısı Şimşon'a eşlik eden arkadaşına verildi."]],15:[["1","Ancak bir süre sonra buğday hasadı sırasında Şimşon, yanında bir oğlakla birlikte karısını ziyaret etti. “Karımın odasına gireceğim” dedi. Ama babası onun içeri girmesine izin vermedi."],["2","Babası şöyle dedi: “Senin ondan kesin olarak nefret ettiğini düşündüm; bu yüzden onu arkadaşına verdim. Küçük kız kardeşi ondan daha güzel değil mi? Lütfen onun yerine onu al.”"],["3","Şimşon onlara şöyle dedi: “Bu sefer Filistliler'e zarar verdiğimde onlardan dolayı suçsuz olacağım.”"],["4","Şimşon gidip üç yüz tilki yakaladı, meşaleler aldı, kuyruk kuyruğa çevirdi ve her iki kuyruğun ortasına bir meşale koydu."],["5","Meşaleleri ateşe verip onları Filistliler'in ekinlerine saldı ve hem demetleri, hem ekinleri, hem de zeytinliklerini yaktı."],["6","Bunun üzerine Filistliler, “Bunu kim yaptı?” diye sordular. Onlar, “Timnalı'nın damadı Şimşon, çünkü onun karısını alıp arkadaşına verdi” dediler. Filistliler gelip onu ve babasını ateşle yaktılar."],["7","Şimşon onlara, “Eğer böyle davranırsanız, kesinlikle sizden öç alırım ve ondan sonra da dururum” dedi."],["8","Onların kalça ve uyluğunu büyük bir kıyımla vurdu; ve inip Etam'ın kayasındaki mağarada yaşadı."],["9","Bunun üzerine Filistliler Yahuda'ya çıkıp ordugâh kurdular ve Lehi'ye yayıldılar."],["10","Yahudalılar, “Neden bize karşı çıktınız?” dediler. “Şimşon'u bağlamak ve bize yaptığı gibi ona yapmak için geldik” dediler."],["11","Bunun üzerine üç bin Yahudalı adam Etam kayasındaki mağaraya inip Şimşon'a şöyle dediler: “Filistliler'in üzerimizde hükmettiklerini bilmiyor musun? Peki bize yaptığın bu nedir?” Onlara, “Onların bana yaptığını ben de onlara yaptım” dedi."],["12","Ona, “Seni bağlamak ve Filistliler'in eline teslim etmek için geldik” dediler. Şimşon onlara, “Bana kendiniz saldırmayacağınıza dair bana ant için” dedi."],["13","Onunla konuşup dediler: “Hayır, ama seni sağlam bir şekilde bağlayıp onların ellerine teslim edeceğiz; ama seni kesinlikle öldürmeyeceğiz.” Onu iki yeni urganla bağlayıp kayadan çıkardılar."],["14","Lehi'ye geldiğinde, Filistliler onunla karşılaşınca bağırdılar. O zaman Yahve'nin Ruhu kuvvetle onun üzerine geldi ve kollarındaki urganlar ateşle yanmış keten gibi oldu; ve ellerinden bağları düştü."],["15","Bir eşeğin taze çene kemiğini buldu, elini uzatıp aldı, onunla da bin insana vurdu."],["16","Şimşon şöyle dedi: “Bir eşeğin çene kemiğiyle yığın üstüne yığın; bir eşeğin çene kemiğiyle bin kişi vurdum.”"],["17","Konuşmasını bitirince çene kemiğini elinden attı; ve oraya Ramat Lehi adı verildi."],["18","Çok susamıştı ve Yahve'ye seslenip dedi: “Sen bu büyük kurtuluşu hizmetkârının eliyle verdin; şimdi susuzluktan öleceğim ve sünnetsizlerin eline mi düşeceğim?”"],["19","Ama Tanrı Lehi'deki çukuru yardı ve oradan su çıktı. İçtiğinde ruhu geri geldi ve canlandı. Bu nedenle En Hakkore adıyla anılmıştır ve bugüne dek Lehi'dedir."],["20","Filistliler'in günlerinde İsrael'e yirmi yıl hükmetti."]],16:[["1","Şimşon Gaza'ya gitti, orada bir fahişe gördü ve yanına girdi."],["2","Gazalılar'a, “Şimşon burada!” diye söylendi. Etrafını sardılar ve bütün gece kentin kapısında ona karşı pusuya yattılar, bütün gece de sessiz kalıp şöyle dediler: “Gün ağarana dek bekleyin; sonra onu öldüreceğiz.”"],["3","Şimşon gece yarısına kadar yattı, sonra gece yarısı kalktı, kent kapısının kanatlarını iki direğiyle tuttu, sürgüyle birlikte hepsini kopardı, omuzlarına attı ve Hevron'un karşısındaki dağın tepesine taşıdı."],["4","Sonradan Sorek Vadisi'nde adı Delila olan bir kadına aşık oldu."],["5","Filistliler'in beyleri kadının yanına çıkıp şöyle dediler: “Onu kandır ve büyük gücünün nereden kaynaklandığını gör; onu bağlayıp ezmek için neyle ona karşı galip gelebiliriz; ve her birimiz sana bin yüz parça gümüş vereceğiz.”"],["6","Delila Şimşon'a, “Lütfen bana büyük gücünün nereden kaynaklandığını ve seni ezmek için neyle bağlanabileceğini söyle” dedi."],["7","Şimşon ona, “Eğer beni kurumamış yedi yeşil sırımla bağlarlarsa, o zaman zayıflarım ve başka bir adam gibi olurum” dedi."],["8","Bunun üzerine Filistliler'in beyleri ona kurumamış yedi yeşil sırım getirdiler ve o da onu onlarla bağladı."],["9","Şimdi kadının iç odada bekleyen bir pususu vardı. Ona, “Filistliler senin üzerinde, Şimşon!” dedi. Kendir ipliğinin ateşe değince koptuğu gibi o da sırımları kopardı. Bu yüzden gücü bilinmiyordu."],["10","Delila Şimşon'a şöyle dedi: “İşte, sen benimle alay ettin, bana yalanlar söyledin. Şimdi lütfen bana nasıl bağlanabileceğini söyle.”"],["11","O da ona, “Eğer beni hiçbir iş yapılmamış yeni urganlarla bağlarlarsa, o zaman zayıf olurum ve başka bir adam gibi olurum” dedi."],["12","Delila yeni urganlar alıp onu bunlarla bağladı ve ona, “Filistliler senin üzerinde, Şimşon!” dedi. Pusu iç odada bekliyordu. Onları iplik gibi kollarından kopardı."],["13","Delila Şimşon'a şöyle dedi: “Şimdiye kadar benimle alay ettin, bana yalanlar söyledin. Neyle bağlanılabileceğini bana söyle.” Ona, “Eğer başımın yedi örgüsünü tezgahtaki kumaşla birlikte dokursan” dedi."],["14","Kadın onu kazıkla tutturdu ve ona, “Filistliler senin üzerinde, Şimşon!” dedi. Uykusundan uyandı ve tezgâh kazığını ve kumaşı kopardı."],["15","Kadın ona şöyle dedi: “Yüreğin benimle değilken nasıl 'Seni seviyorum' diyebilirsin? Benimle bu üç kezdir alay ettin ve bana büyük gücünün nereden kaynaklandığını söylemedin.”"],["16","Her gün sözleriyle onu sıkıştırıp baskı yapınca, canı ölesiye sıkıntıya girdi."],["17","Yüreğini tümüyle ona anlattı ve şöyle dedi: “Başıma hiç ustura değmedi; çünkü ben ana rahminden Tanrı'nın Adanmışı'yım. Eğer tıraş olursam, o zaman gücüm benden gider, zayıf düşerim ve herkes gibi olurum.”"],["18","Delila onun yüreğini tümüyle kendisine bildirdiğini görünce, Filistliler'in beylerini çağırıp şöyle dedi: “Bu kez de çıkın, çünkü o bana tüm yüreğini anlattı.” Sonra Filistliler'in beyleri onun yanına çıktılar, parayı ellerinde getirdiler."],["19","Onu dizlerinin üzerinde uyuttu; ve bir adam çağırıp başının yedi örgüsünü tıraş ettirdi; ve ona eziyet etmeye başladı ve gücü ondan gitti."],["20","“Filistliler senin peşinde, Şimşon!” dedi. Uykusundan uyandı ve şöyle dedi: “Diğer zamanlarda olduğu gibi çıkar silkinirim.” Ama Yahve'nin kendisinden ayrılmış olduğunu bilmiyordu."],["21","Filistliler onu tutup gözlerini oydular; ve onu Gaza'ya indirip tunç zincirlerle bağladılar; ve hapishanede değirmen çeviriyordu."],["22","Ancak tıraş olduktan sonra başındaki saçlar yeniden çıkmaya başladı."],["23","Filistliler'in beyleri, ilâhları Dagon'a büyük bir kurban sunmak ve sevinmek için toplandılar; çünkü, “İlâhımız, düşmanımız Şimşon'u elimize teslim etti” dediler."],["24","Halk onu görünce ilâhlarını övdüler; çünkü şöyle dediler, “Ülkemizi harap eden, bir çoğumuzu katleden düşmanımızı ilâhımız elimize teslim etti.”"],["25","Yürekleri neşelenince, “Şimşon'u çağırın da bizi eğlendirsin” dediler. Şimşon'un hapishaneden çıkması için çağrıda bulundular; ve onların önünde oynadı. Onu sütunların arasına koydular;"],["26","Şimşon elinden tutan gence, “İzin ver, evin üzerinde dayandığı sütunlara dokunayım da onlara yaslanayım” dedi."],["27","Ev erkeklerle ve kadınlarla doluydu; Filistliler'in bütün beyleri oradaydı; ve Şimşon'un oynamasını gören yaklaşık üç bin erkek ve kadın damın üzerindeydi."],["28","Şimşon Yahve'ye seslenip şöyle dedi: “Ey Efendim Yahve, lütfen beni hatırla, lütfen, yalnız bu seferlik beni güçlendir, ey Tanrı, iki gözümün öcünü Filistliler'den birden alayım.”"],["29","Şimşon, evin üzerinde durduğu ortadaki iki sütunu tuttu; biri sağ eliyle, öbürü sol eliyle onlara yaslandı."],["30","Şimşon, “Filistliler'le birlikte öleyim!” dedi. Bütün gücüyle eğildi; ve ev beylerin ve içinde olan bütün halkın üzerine düştü. Böylece ölümünde öldürdüğü ölüler, hayatında öldürdüğünden daha fazlaydı."],["31","Bunun üzerine kardeşleri ve babasının bütün ev halkı indiler onu aldılar ve onu kaldırıp Sora ile Eştaol arasında, babası Manoah'ın mezarına gömdüler. O İsrael'e yirmi yıl hükmetmişti."]],17:[["1","Efraim'in dağlık bölgesinde Mika adında bir adam vardı."],["2","Annesine şöyle dedi: “Senden alınmış olan, hakkında lanet ettiğin, bunu kulaklarıma da söylediğin bin yüz gümüş, işte gümüş yanımda. Onu ben aldım.” Annesi, “Yahve oğlumu kutsasın!” dedi."],["3","Bin yüz parça gümüşü annesine geri verdi, sonra annesi şöyle dedi: “Gümüşü oğlum için bir oyma suret ve bir dökme suret yapmak üzere tarafımdan Yahve'ye kesin bir şekilde adadım. Bu yüzden şimdi onu sana geri vereceğim.”"],["4","Parayı annesine geri verince, annesi iki yüz parça gümüş alıp bunları bir gümüşçüye verdi; o da bundan oyma bir suret ve dökme bir suret yaptı. Mika'nın evindeydi."],["5","Mika denen adamın ilâhlar evi vardı; bir efod ve terafim yaptı ve oğullarından birini kutsadı, o da kendisine kâhin oldu."],["6","O günlerde İsrael'de kral yoktu. Herkes kendi gözünde doğru olanı yapardı."],["7","Beytlehem Yahuda'dan, Yahuda soyundan Levili bir genç vardı; ve orada yaşıyordu."],["8","Adam bulabildiği bir yerde yaşamak üzere kentten, Beytlehem Yahuda'dan ayrıldı; yolculuk sırasında Efraim'in dağlık bölgesine, Mika'nın evine geldi."],["9","Mika ona, “Nereden geldin?” dedi. Ona, “Ben Beytlehem Yahuda'dan bir Levili'yim ve yaşayacak bir yer arıyorum” dedi."],["10","Mika ona, “Benimle otur, bana baba ve kâhin ol” dedi, “Sana yılda on parça gümüş, bir elbise ve yiyeceğini vereceğim.” Böylece Levili içeri girdi."],["11","Levili adamın yanında oturmaktan memnundu; genç adam da onun için oğullarından biri gibiydi."],["12","Mika Levili'yi kutsadı ve genç adam onun kâhini oldu ve Mika'nın evindeydi."],["13","Bunun üzerine Mika, “Kâhinim bir Levili olduğundan, Yahve'nin bana iyilik edeceğini artık biliyorum” dedi."]],18:[["1","O günlerde İsrael'de kral yoktu. O günlerde Danlılar oymağı oturacak bir miras arıyordu; çünkü o güne dek İsrael boyları arasında mirasları onlara düşmemişti."],["2","Dan'ın çocukları ülkeyi gözetlemek ve araştırmak üzere kendi soylarından, bütün sayılarından, Sorah ve Eştaol'dan beş kişiyi, cesur yiğitler gönderdiler. Onlara, “Gidin, ülkeyi araştırın!” dediler. Efraim'in dağlık bölgesine, Mika'nın evine gelip orada konakladılar."],["3","Mika'nın evinin yanındayken Levili gencin sesini tanıdılar; bunun üzerine oraya gittiler ve ona dediler: “Seni buraya kim getirdi? Bu yerde ne yapıyorsunuz? Burada neyin var?”"],["4","Onlara şöyle dedi: “Mika bana böyle böyle davrandı, beni ücretli tuttu ve onun kâhini oldum.”"],["5","Ona, “Lütfen Tanrı'dan öğüt iste de, gideceğimiz yolun başarılı olup olmayacağını bilelim” dediler."],["6","Kâhin onlara, “Esenlikle gidin” dedi. “Gideceğiniz yol Yahve'nin önündedir.”"],["7","Bunun üzerine beş adam ayrılıp Laiş'e geldiler ve orada bulunan halkın Saydalılar'ın yaşadığı gibi güvenlik içinde, sakin ve emniyette yaşadıklarını gördüler; çünkü ülkede onları herhangi bir şeyde utandıracak hüküm sahibi kimse yoktu ve Saydalılar'dan uzaktılar ve başka kimseyle ilişkileri yoktu."],["8","Sorah ve Eştaol'daki kardeşlerinin yanına geldiler; ve kardeşleri onlara, “Ne diyorsunuz?” diye sordular."],["9","Onlar, “Kalkın, onlara karşı çıkalım” dediler. “Çünkü diyarı gördük ve işte, orası çok iyidir. Hâlâ kımıldamıyor musunuz? Diyarı mülk edinmek için gitmekte ve girmekte tembel olmayın."],["10","Gittiğinizde kuşkulanmayan bir halkın yanına varacaksınız. Ülke geniştir; çünkü Tanrı orayı, yeryüzünde hiçbir şeyin eksik olmadığı bir yeri elinize verdi.”"],["11","Danlılar soyu, savaş silahları kuşanmış altı yüz adamla birlikte Sora ve Eştaol'dan yola çıktı."],["12","Yahuda'ya çıkıp Kiryat Yearim'de konakladılar. Bu nedenle bugüne kadar o yere Mahaneh Dan denilir. İşte, Kiryat Yearim'in arkasındadır."],["13","Oradan Efraim'in dağlık bölgesine geçip Mika'nın evine geldiler."],["14","O zaman Laiş ülkesine araştırmaya giden beş adam yanıt verip kardeşlerine şöyle dediler: “Bu evlerde efod, terafim, oyma suret ve dökme suret olduğunu biliyor musunuz? Şimdi ne yapmanız gerektiğini düşünün.”"],["15","Oraya giderek Levili genç adamın evine, Mika'nın evine kadar gelip ona nasıl olduğunu sordular."],["16","Dan'ın çocuklarından savaş silahlarıyla kuşanmış altı yüz adam kapı girişi yanında duruyordu."],["17","Ülkeyi araştırmak için giden beş adam çıkıp oraya geldiler, oyma sureti, efodu, terafimi ve dökme sureti aldılar; ve kâhin, savaş silahlarıyla donanmış altı yüz adamla birlikte kapı girişinin yanında duruyordu."],["18","Bunlar Mika'nın evine gidip oyma sureti, efodu, terafimi ve dökme sureti aldıklarında, kâhin onlara, “Ne yapıyorsunuz?” dedi."],["19","Ona, “Sus, elini ağzının üzerine koy ve bizimle gel” dediler. “Bize baba ve kâhin ol. Senin için bir adamın evine kâhin olmak mı daha iyi, yoksa İsrael'de bir oymağa ve bir soya kâhin olmak mı?”"],["20","Kâhinin yüreği sevindi ve efodu, terafimi ve oyma sureti alıp halkla birlikte gitti."],["21","Bunun üzerine dönüp gittiler; çocukları, hayvanları ve malları önlerine koydular."],["22","Mika'nın evinden epey uzaklaşınca, Mika'nın evinin yakınındaki evlerde bulunan adamlar toplanıp Dan'ın çocuklarına yetiştiler."],["23","Onlar Dan'ın çocuklarına seslenince yüzlerini çevirip Mika'ya dediler: “Neden böyle bir toplulukla geldin?”"],["24","O, “Yaptığım ilâhları ve kâhini alıp gittiniz” dedi. “Başka neyim kaldı? Bana, 'Neyin var?' diye nasıl sorarsınız?”"],["25","Dan'ın çocukları ona şöyle dediler: “Aramızda sesini duyurma, yoksa öfkeli adamlar sana saldıracak ve kendi hayatını ev halkının hayatlarını kaybedeceksin.”"],["26","Dan'ın çocukları yollarına gittiler; Mika onların kendisi için çok güçlü olduklarını görünce dönüp evine gitti."],["27","Mika'nın yapmış olduğu ve sahip olduğu kâhini alıp Laiş'e gelerek sessiz ve kuşkulanmayan halkın yanına geldiler ve onları kılıçtan geçirdiler; sonra kenti ateşle yaktılar."],["28","Kurtaran yoktu, çünkü Sayda'dan uzaktı ve başka kimseyle ilişkileri yoktu; Beyt Rehov'un yanındaki vadideydi. Kenti bina ettiler ve içinde yaşadılar."],["29","İsrael'e doğmuş olan babaları Dan'ın adı ardınca kentin adını Dan koydular; ancak kentin eski adı Laiş'ti."],["30","Dan'ın çocukları oyma sureti kendileri için diktiler; Moşe oğlu Gerşom oğlu Yonatan, kendisi ve oğulları, ülkenin sürgününe dek Dan oymağının kâhinleriydi."],["31","Böylece Mika'nın yaptığı oyma sureti kendileri için diktiler; ve Tanrı'nın evi Şilo'da olduğu sürece o suret orada kaldı."]],19:[["1","İsrael'de kralın olmadığı o günlerde, Efraim'in dağlık bölgesinin uzak tarafında yaşayan bir Levili vardı ve Beytlehem Yahuda'dan kendine bir cariye almıştı."],["2","Cariyesi ona karşı fahişelik etti ve ondan ayrılıp babasının evine, Beytlehem Yahuda'ya gitti ve orada dört ay kaldı."],["3","Kocası kalktı, onunla yumuşak bir şekilde konuşmak ve onu geri getirmek için, yanında hizmetçisi ve birkaç eşekle birlikte onun peşinden gitti. Kadın onu babasının evine getirdi; ve genç kadının babası onu görünce onu sevinçle karşıladı."],["4","Genç kadının babası kayınpederi onu orada tuttu; ve üç gün onun yanında kaldı. Böylece yediler, içtiler ve orada kaldılar."],["5","Dördüncü gün sabah erkenden kalktılar, o da yola çıkmak üzere kalktı. Genç kadının babası damadına, “Bir lokma ekmekle yüreğini güçlendir, sonra yoluna gidersin” dedi."],["6","Hep birlikte oturdular, yiyip içtiler. Bunun üzerine genç kadının babası adama şöyle dedi: “Lütfen bütün geceyi burada geçirmekten memnun ol, yüreğin de neşelensin.”"],["7","Adam ayrılmak üzere ayağa kalktı; ama kayınpederi onu zorladı, o da yine orada kaldı."],["8","Beşinci gün yola çıkmak üzere sabah erkenden kalktı; ve genç kadının babası şöyle dedi: “Lütfen yüreğini güçlendir ve gün batana dek kalın.” ve ikisi de yediler."],["9","Adam, cariyesi, hizmetçisi ile ayrılmak üzere kalktığında, kayınpederi, genç kadının babası ona şöyle dedi: “İşte, artık gün akşama yakınlaşıyor, lütfen bütün gece kalın. Bakın gün bitiyor. Burada kal ki, yüreğin neşelensin; yarın erkenden yola çıkar evine gidersin.”"],["10","Ama adam o gece orada kalmadı, ama kalkıp Yevus'un (Yeruşalem olarak da bilinir) yanına gitti. Yanında eyerlenmiş birkaç eşek vardı. Cariyesi de yanındaydı."],["11","Yevus'un yakınındayken gün çoktan geçmişti; hizmetçi efendisine, “Lütfen gel, Yevuslular'ın bu kentine girelim ve orada kalalım” dedi."],["12","Efendisi ona şöyle dedi: “İsrael'in çocuklarından olmayan bir yabancının kentine girmeyeceğiz; ama biz Giva’ya geçeceğiz.”"],["13","Uşağına, “Gel, bu yerlerden birine yaklaşalım; ve Giva'da ya da Rama'da konaklayacağız” dedi."],["14","Böylece geçip gittiler; ve Benyamin'e ait olan Giva yakınında güneş üzerlerine battı."],["15","Giva'da kalmak üzere oraya girdiler. İçeri girdi ve şehrin sokağına oturdu; çünkü onları kalmaları için evine götüren kimse yoktu."],["16","İşte akşamleyin kırdan yaşlı bir adam işinden geliyordu. Adam Efraim'in dağlık bölgesindendi ve Giva'da yaşıyordu; ama o yerin adamları Benyaminli'ydi."],["17","Gözlerini kaldırdı ve kentin sokağındaki yolcuyu gördü; ve yaşlı adam şöyle dedi: “Nereye gidiyorsun? Nereden geldin?”"],["18","O da ona şöyle dedi: “Beytlehem Yahuda'dan Efraim'in dağlık bölgesinin uzak tarafına geçiyoruz. Ben oradanım ve Beytlehem Yahuda'ya gittim. Yahve'nin evine gidiyorum; ve beni evine alan kimse yok."],["19","Oysa eşeklerimiz için hem saman hem de yem var; ve benim için, hizmetkârın için ve hizmetkârlarınla birlikte olan genç için de ekmek ve şarap var. Hiçbir şey eksik değil.”"],["20","Yaşlı adam şöyle dedi: “Size esenlik olsun! Bütün ihtiyaçlarınızı ben karşılayayım ama sakın sokakta uyumayın.”"],["21","Bunun üzerine onu evine getirip eşeklere yem verdi. Daha sonra ayaklarını yıkadılar, yiyip içtiler."],["22","Onlar yüreklerini neşelendirirken, işte, kentin adamları, bazı kötü adamlar evin etrafını sardılar, kapıyı vurdular; evin efendisi olan yaşlı adamla konuşup şöyle dediler: “Evine gelen adamı dışarı çıkar da onunla yatalım!”"],["23","Evin sahibi olan adam yanlarına çıkıp şöyle dedi: “Hayır, kardeşlerim, lütfen bu kadar kötü davranmayın; madem bu adam evime geldi, bu deliliği yapmayın."],["24","İşte, el değmemiş kızımla cariyesi burada. Şimdi onları dışarı çıkaracağım. Onları alçaltın ve onlara size iyi gelene göre yapın; ama bu adama böyle bir delilik yapmayın.”"],["25","Ama adamlar onu dinlemediler; adam cariyesini tutup yanlarına çıkardı; ve onunla yattılar ve bütün gece sabaha kadar ona kötü davrandılar. Gün ağarmaya başlayınca onu salıverdiler."],["26","Bunun üzerine kadın gün ağarırken geldi ve hava aydınlanıncaya kadar efendisinin bulunduğu adamın evinin kapısı önünde yere kapandı."],["27","Efendisi sabah kalktı, evin kapılarını açtı ve yola çıkmak üzere dışarı çıktı; ve işte, cariyesi kadın, elleri eşikte, evin kapısında yere düşmüştü."],["28","Ona, “Kalk, gidelim!” dedi ama kimse yanıt vermedi. Sonra onu eşeğe bindirdi; ve adam kalkıp kendi yerine gitti."],["29","Evine vardığında bir bıçak alıp cariyesini parçaladı, onu uzuv uzuv on iki parçaya böldü ve onu bütün İsrael sınırlarına gönderdi."],["30","Öyle oldu ki, bunu gören herkes şöyle dedi: “İsrael çocuklarının Mısır'dan çıktığı günden bu güne dek böyle bir şey ne yapıldı, ne de görüldü! Düşünün, öğütleşin ve konuşun.”"]],20:[["1","Bunun üzerine bütün İsrael'in çocukları çıktılar ve Gilad ülkesiyle Dan'dan Beerşeva'ya kadar topluluk bir adammış gibi Mispa'da Yahve'nin önünde toplandı."],["2","Bütün halkın, İsrael'in bütün oymaklarının ileri gelenleri, kılıç çeken dört yüz bin yaya, Tanrı halkının toplantısında kendilerini sundular."],["3","(Benyamin'in çocukları, İsrael'in çocuklarının Mispa'ya çıkmış olduklarını duydular.) İsrael'in çocukları, “Söyle bize, bu kötülük nasıl oldu?” dediler."],["4","Öldürülen kadının kocası Levili şöyle yanıt verdi: “Cariyemle birlikte geceyi geçirmek üzere Benyamin'in Giva'sına geldim."],["5","Givalılar bana karşı kalktılar ve geceleyin evi kuşattılar. Beni öldürmek istediler, cariyeme tecavüz ettiler, o da öldü."],["6","Cariyemi alıp onu parçalara ayırdım ve onu İsrael'in mirası olan bütün memlekete gönderdim; çünkü İsrael'de namussuzluk ve delilik yaptılar."],["7","İşte, ey İsrael'in çocukları, hepiniz burada önerinizi ve öğüdünüzü verin.”"],["8","Bütün halk tek bir adammış gibi ayağa kalkıp şöyle dedi: “Hiçbirimiz çadırına gitmeyecek, hiçbirimiz evine dönmeyecek."],["9","Ama şimdi Giva'ya şunu yapacağız: Ona kurayla karşı çıkacağız;"],["10","ve halk için yiyecek sağlamak üzere İsrael'in bütün oymaklarından yüz kişiden on, bin kişiden yüz ve on bin kişiden bin kişi alacağız, ve Benyamin'in Giva'sına gelince, onlar Givalılar'ın İsrael'de yaptıkları bütün deliliğe göre yapsınlar.”"],["11","Böylece bütün İsraelliler o kente karşı toplanıp bir adammış gibi birleştiler."],["12","İsrael oymakları Benyamin oymağının her yerine adamlar gönderip şöyle dediler: “Aranızda gerçekleşen bu kötülük nedir?"],["13","Şimdi Giva'daki adamları, kötü adamları teslim edin ki, onları öldürelim ve İsrael'den kötülüğü kaldıralım.'' Ancak Benyamin kardeşleri İsrael'in çocuklarının sesine kulak vermedi."],["14","Benyamin'in çocukları İsrael'in çocuklarına karşı savaşmak üzere kentlerden Giva'ya doğru toplandılar."],["15","O gün Benyamin'in çocuklarından kentlerden kılıç çeken yirmi altı bin kişi sayıldı; buna ek olarak Giva sakinlerinden yedi yüz seçilmiş adam sayıldı."],["16","Bütün bu askerler arasında solak yedi yüz seçme adam vardı. Her biri sapanla bir kıla taş atabilir ve ıskalamazdı."],["17","İsrael'in çocukları Benyamin'in yanı sıra kılıç çeken dört yüz bin kişi sayıldı. Bunların hepsi savaş adamlarıydı."],["18","İsrael'in çocukları kalkıp Beytel'e gittiler ve Tanrı'dan öğüt istediler. “Benyamin'in çocuklarına karşı savaşmak için ilk kim bizim için çıkacak?” diye sordular. Yahve, “İlk Yahuda” dedi."],["19","İsrael'in çocukları sabah kalkıp Giva'ya karşı ordugâh kurdular."],["20","İsraelliler Benyamin'e karşı savaşmaya çıktılar; ve İsrael adamları Giva'da onlara karşı savaşa dizildiler."],["21","Benyamin'in çocukları Giva'dan çıkıp o gün İsraelliler'den yirmi iki bin kişiyi yere serdi."],["22","Halk, İsrael adamları, kendilerini cesaretlendirdiler ve ilk gün savaşa dizildikleri yerde yeniden dizildiler."],["23","İsrael'in çocukları çıkıp akşama kadar Yahve'nin önünde ağladılar; ve Yahve'ye sorup dediler: “Kardeşimiz Benyamin'in çocuklarına karşı savaşmak için tekrar yaklaşalım mı?” Yahve, “Ona karşı çıkın” dedi."],["24","İkinci gün İsrael'in çocukları Benyamin'in çocuklarına yaklaştılar."],["25","Benyamin ikinci gün Giva'dan onlara karşı çıktı ve yine İsrael'in çocuklarından on sekiz bin kişiyi yere serdi. Bunların hepsi kılıç çekenlerdi."],["26","Bunun üzerine bütün İsrael'in çocukları ve bütün halk çıkıp Beytel'e geldiler, ağladılar, orada Yahve'nin önünde oturdular ve o gün akşama kadar oruç tuttular; sonra Yahve'nin önünde yakmalık sunular ve esenlik sunuları sundular."],["27","İsrael'in çocukları Yahve'ye sorup (çünkü Tanrı'nın Antlaşma Sandığı o günlerde oradaydı;"],["28","ve Aron oğlu Eleazar oğlu Pinehas o günlerde onun önünde duruyordu) şöyle dediler: “Kardeşimiz Benyamin'in çocuklarına karşı savaşmaya yine bir daha çıkalım mı, yoksa duracak mıyız?” Yahve şöyle dedi: “Çıkın; çünkü yarın onları sizin elinize teslim edeceğim.”"],["29","İsrael Giva'nın her yerinde pusu kurdu."],["30","İsrael'in çocukları üçüncü gün Benyamin'in çocuklarına karşı çıktılar ve diğer zamanlarda olduğu gibi Giva'ya karşı dizildiler."],["31","Benyamin'in çocukları halka karşı çıktılar ve kentten uzaklaştırıldılar; ve başka zamanlarda olduğu gibi, biri Beytel'e, diğeri kırdan Giva'ya giden ana yollarda, halktan vurmaya başladılar, otuz kadar İsraelli'yi öldürdüler."],["32","Benyamin'in çocukları, “İlk başta olduğu gibi önümüzde vuruldular” dediler. Ama İsrael'in çocukları, “Kaçalım ve onları kentten ana yollara çekelim” dediler."],["33","İsrael'in bütün erkekleri yerlerinden kalkıp Baal Tamar'da dizildiler. Bunun üzerine İsrael'in pusuda yatanları yerlerinden, Maare Geva'dan fırladılar."],["34","Bütün İsrael'den on bin seçme adam Giva'ya karşı geldi; savaş şiddetliydi; ama felaketin kendilerine yakın olduğunu bilmiyorlardı."],["35","Yahve Benyamin'i İsrael'in önünde vurdu; ve İsrael'in çocukları o gün Benyamin'den yirmi beş bin yüz kişiyi yok ettiler. Bunların hepsi kılıç çekenlerdi."],["36","Böylece Benyamin'in çocukları vurulduklarını gördüler; çünkü İsraelliler Giva'ya karşı kurdukları pusuculara güvendikleri için Benyamin'e yol vermişlerdi."],["37","Pusu kuranlar aceleyle Giva'ya saldırdılar; bunun üzerine pusu kuranlar dağılıp bütün kenti kılıçtan geçirdiler."],["38","İsraelliler ile pusu kuranlar arasındaki belirlenmiş olan işaret, kentten büyük bir duman bulutu çıkarmalarıydı."],["39","İsraelliler savaşta geri döndüler. Benyamin vurmaya başlayarak İsraelliler'den otuz kadar kişiyi öldürdü. Çünkü onlar, “Onlar belli ki, ilk savaşta olduğu gibi önümüzde vuruldular” dediler."],["40","Ama bulut bir duman sütunu halinde kentin içinden yükselmeye başlayınca, Benyamin'in çocukları arkalarına baktılar; ve işte, bütün kent dumanlar içinde gökyüzüne yükseliyordu."],["41","İsraelliler geri döndüler, Benyaminliler dehşete düştüler; çünkü üzerlerine felaket gelmiş olduğunu gördüler."],["42","Bu nedenle İsraelliler'in önünde çöl yoluna sırtlarını döndüler, ama savaş onları sert bir şekilde takip etti; ve kentlerden çıkanlar onları ortalarında yok ettiler."],["43","Benyaminiler'in etrafını sardılar, kovaladılar ve gün doğumuna doğru Giva yakınlarına kadar dinlenme yerlerinde onları çiğnediler."],["44","Benyaminliler'den on sekiz bin kişi düştü; bunların hepsi cesur yiğitlerdi."],["45","Dönüp çöldeki Rimmon Kayası'na doğru kaçtılar. Ana yollarda onlardan beş bin kişiyi topladılar ve Gidom'a kadar sıkı bir şekilde peşlerine düştüler ve iki bin kişiyi vurdular."],["46","Böylece Benyamin'den o gün ölenlerin hepsi, kılıç çeken yirmi beş bin kişiydi. Bunların hepsi cesur yiğitlerdi."],["47","Ama altı yüz kişi dönüp çöldeki Rimmon Kayası'na kaçtılar ve Rimmon Kayası'nda dört ay kaldılar."],["48","İsraelliler yine Benyamin'in çocuklarına karşı döndüler ve onları, bütün kenti, hayvanları ve buldukları her şeyi kılıçtan geçirdiler. Dahası buldukları bütün kentleri ateşe verdiler."]],21:[["1","İsraelliler Mispa'da ant içerek şöyle dediler: “Hiçbirimiz kızını Benyamin'e eş olarak vermeyeceğiz.”"],["2","Halk Beytel'e gelip orada akşama kadar Tanrı'nın önünde oturdular, seslerini yükseltip şiddetle ağladılar."],["3","Onlar, “Ey Yahve, İsrael'in Tanrısı, neden İsrael'de böyle oldu da bugün İsrael'de bir oymak eksildi?” dediler."],["4","Ertesi gün halk erkenden kalktı, orada bir sunak yaptı, yakmalık sunularla esenlik sunuları sundu."],["5","İsrael'in çocukları, “Bütün İsrael oymaklarından toplantıda Yahve'ye çıkmayan kim var?” dediler. Çünkü Mispa'da Yahve'ye çıkmayan adam için, “Mutlaka öldürülecektir” diyerek büyük ant içmişlerdi."],["6","İsrael'in çocukları, kardeşleri Benyamin için üzülüp şöyle dediler: “Bugün İsrael'den kopmuş bir oymak var."],["7","Kızlarımızı onlara eş olarak vermeyeceğimize Yahve'ye ant içtiğimize göre, geride kalanlara nasıl eşler sağlayacağız?”"],["8","“İsrael oymaklarından Mispa'ya, Yahve'ye çıkmayan kim var?” dediler. İşte, Yaveş Gilad'dan ordugâha, toplantıya kimse gelmemişti."],["9","Çünkü halk sayıldığında, orada Yaveş Gilad sakinlerinden kimse yoktu."],["10","Topluluk oraya en cesur adamlardan on iki binini göndererek onlara şu buyruğu verdi: “Gidin, kadınlar ve küçük çocuklarla birlikte Yaveş Gilad halkını kılıçtan geçirin."],["11","Yapacağın şey şudur: Her erkeği, erkekle yatmış olan her kadını tamamen yok edeceksiniz.”"],["12","Yaveş Gilad sakinleri arasında, erkek bilmeyen, el değmemiş dört yüz genç kız buldular; ve onları Kenan ülkesinde bulunan Şilo'daki ordugâha getirdiler."],["13","Bütün topluluk, Rimmon Kayası'nda bulunan Benyamin'in çocuklarına adam gönderip onlarla konuştu ve onlara barış ilan etti."],["14","O sırada Benyamin geri döndü; ve Yaveş Gilad kadınlarından canlı olarak kurtardıkları kadınları onlara verdiler. Hâlâ onlara yetmiyordu."],["15","Yahve İsrael oymaklarına gedik açtığı için halk Benyamin için yas tuttu."],["16","Bunun üzerine topluluğun ihtiyarları, “Benyamin'in kadınları yok edildiğine göre, geride kalanlara nasıl eşler sağlayacağız?” dediler."],["17","Onlar şöyle dediler: “Benyamin'den kurtulanlara bir miras verilmeli ki, İsrael'den bir oymak silinmesin."],["18","Ancak onlara kızlarımızdan eşler veremeyiz; çünkü İsrael'in çocukları, 'Benyamin'e eş verene lanet olsun' diyerek ant içmişlerdi.”"],["19","Onlar, “İşte, Beytel'in kuzeyinde, Beytel'den Şekem'e çıkan yolun doğusunda ve Lebona'nın güneyinde bulunan Şilo'da Yahve'nin yıldan yıla bir bayramı vardır” dediler."],["20","Benyamin'in çocuklarına şu buyruğu verip dediler: “Gidin, bağlarda pusuya yatın;"],["21","ve bakın, ve işte, eğer Şilo kızları dans etmek için çıkarlarsa, o zaman bağlardan çıkın ve her adam kendine eş olarak Şilo kızlarından yakalasın ve Benyamin ülkesine gidin."],["22","Öyle olacak ki, babaları ya da kardeşleri bize şikayette bulunmak için geldiklerinde onlara şöyle diyeceğiz: 'Onları bize lütfederek bağışlayın; çünkü biz savaşta her birine bir eş almadık, ne de siz onlara verdiniz; yoksa şimdi suçlu olurdunuz.'”"],["23","Benyamin'in çocukları da öyle yaptılar ve kendi sayılarına göre dans edenlerden alıp götürdüler. Gidip miraslarına döndüler, kentler bina ettiler ve onlarda yaşadılar."],["24","O zaman İsrael'in çocukları, her biri kendi oymağına ve ailesine göre oradan ayrıldı ve her biri oradan kendi mirasına çıktı."],["25","O günlerde İsrael'de kral yoktu. Herkes kendi gözünde doğru olanı yapardı."]]};export{a as default};
